/* Original editorial draft; canonical triads are referenced by ID. */
window.HEALTH_DATA={"schemaVersion":1,"meta":{"title":"Códigos de Luz para tu Salud · Diccionario de escucha interior","version":"2026-10-26.salud.1","status":"propuesta_editorial","scope":"Colección inicial de 120 condiciones y temas de salud, abierta a ampliación y revisión del autor; no se presenta como un inventario de todas las enfermedades existentes.","opening":"Conecta con esta vibración para escuchar tu experiencia interior, reconocer lo que pide atención y abrir un espacio de comprensión.","framework":"En la visión de los Códigos de Luz, la Llama expresa la presencia divina que desciende y encuentra expresión en la vida. Esta exploración te invita a recibir esa presencia y llevarla a una intención elegida por ti.","editorialPolicy":"Reflexiones originales propuestas para revisión de Zuluan Orion. Las fuentes médicas fundamentan solo las definiciones generales. Las tríadas conservan el contexto, orden y propósito publicados; la persona elige una intención, no una fórmula asignada por enfermedad. No atribuir causas físicas a emociones, patrones o vibraciones; no prometer efectos clínicos ni cambios de tratamiento.","verifiedDate":"2026-10-26","entryCount":120,"intentionCount":21},"intents":[{"id":"descanso","title":"Descanso y ritmo","description":"Quiero acompañar mi necesidad de descanso.","formulaId":"energy-r60-p728-c0456-f01","sourceRationale":"La tabla de elección del libro vincula esta tríada con recuperar el ritmo y el descanso."},{"id":"claridad","title":"Claridad y comprensión","description":"Quiero distinguir lo que sé, lo que siento y lo que necesito preguntar.","formulaId":"energy-p056-f01","sourceRationale":"La práctica invita a observar antes de concluir y a distinguir los datos de las interpretaciones."},{"id":"expresion","title":"Expresar mi necesidad","description":"Quiero encontrar palabras para una petición o una conversación.","formulaId":"energy-p241-f01","sourceRationale":"La inteligencia Claridad trabaja una frase sencilla que exprese lo que necesitas decir."},{"id":"compasion","title":"Ternura y compasión","description":"Quiero tratarme con amabilidad y reconocer el cuidado que puedo recibir.","formulaId":"energy-r60-p641-c0373-f01","sourceRationale":"La fuente propone reconocer el sufrimiento propio y ajeno y elegir un cuidado útil y posible."},{"id":"apoyo","title":"Presencia y apoyo","description":"Quiero reconocer dónde estoy y qué me sostiene.","formulaId":"energy-p670-f01","sourceRationale":"La práctica invita a reconocer la presencia corporal y los apoyos disponibles."},{"id":"tristeza","title":"Acoger mi tristeza","description":"Quiero dar espacio a una tristeza que estoy sintiendo.","formulaId":"energy-r60-p645-c0377-f01","sourceRationale":"El estado Tristeza se acompaña con acogida, escucha y compañía."},{"id":"limites","title":"Límites y elección","description":"Quiero expresar mi disponibilidad y cuidar mis decisiones.","formulaId":"energy-p099-f01","sourceRationale":"Límite basal acompaña el consentimiento y la posibilidad de elegir cómo te relacionas."},{"id":"escucha_receptiva","title":"Escuchar sin perder mi posición","description":"Quiero escuchar a otra persona sin confundir comprenderla con aceptar todo.","formulaId":"heart-366-f01","sourceRationale":"La entrada distingue acoger lo que otra persona expresa de aceptar todo o abandonar el propio límite.","sourceEvidence":"Puerta con marco: escuchar entero y decir hasta dónde. Se puede acoger completamente y aun así no aceptar todo.","sourcePage":386,"originalTitle":"RECEPTIVIDAD CON LÍMITES","sourceBook":"Códigos de Luz para tu Corazón","sourceContext":"Escucha y límites dentro de una relación; no se asigna esta fórmula por una enfermedad o un síntoma."},{"id":"confianza_discernida","title":"Confiar por grados","description":"Quiero reconocer qué confianza puedo ofrecer y qué necesita más tiempo.","formulaId":"energy-p194-f01","sourceRationale":"Confianza discernida propone graduar la apertura según hechos, tiempo, coherencia y reciprocidad, conservando la libertad de revisarla.","sourceEvidence":"Tu corazón no necesita abrir todas sus puertas a la vez. Una relación va mostrando cómo recibe tu verdad, tu diferencia y tu derecho a decir que no. Deja que la confianza crezca con esa experiencia. La apertura tiene profundidad cuando puedes elegirla y conservar la libertad de revisar cuánto compartes.","sourcePage":188,"originalTitle":"Confianza discernida","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"La confianza se refiere aquí a una relación y a cuánto compartir; no equivale a confianza en un resultado médico."},{"id":"incertidumbre","title":"Dar espacio a lo que todavía no sé","description":"Quiero reconocer lo que observé, lo que interpreto y lo que todavía necesito conocer.","formulaId":"energy-p329-f01","sourceRationale":"Humildad de conocimiento permite honrar una experiencia sin convertir su interpretación en certeza; invita a mantener una pregunta y una conclusión provisional.","sourceEvidence":"Una experiencia puede conmoverte profundamente y aun así dejar abierta su interpretación. La humildad te permite honrar lo vivido sin exigir que otra persona lo reciba como una prueba. Puedes reconocer lo que sabes y conservar amor por lo que todavía no comprendes.","sourcePage":323,"originalTitle":"Humildad de conocimiento","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Se contempla la relación entre experiencia e interpretación; la práctica no confirma explicaciones espirituales de una enfermedad."},{"id":"eleccion_consciente","title":"Elegir un paso posible","description":"Quiero reconocer mis opciones y tomar una decisión provisional sin exigirme certeza total.","formulaId":"energy-p150-f01","sourceRationale":"Elección trabaja distinguir opciones, reconocer lo incierto y asumir una decisión honesta para el momento presente.","sourceEvidence":"Cada elección le da lugar a algo y deja otra posibilidad esperando. Por eso decidir puede doler un poco, incluso cuando eliges bien. La Elección acepta esa condición humana. Mira lo que sabes, reconoce lo incierto y encuentra una respuesta lo bastante honesta para el momento en que estás.","sourcePage":144,"originalTitle":"Elección","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Agencia en decisiones cotidianas; no es una indicación para cambiar tratamientos o decidir asuntos clínicos mediante una tríada."},{"id":"adaptacion","title":"Adaptarme conservando lo esencial","description":"Quiero ajustar mi ritmo o mi manera de hacer algo sin perder lo que valoro.","formulaId":"energy-p120-f01","sourceRationale":"Fluidez adaptativa acompaña un cambio de ritmo o estrategia que conserva identidad, límite y propósito.","sourceEvidence":"La vida cambia de forma. Un acuerdo necesita otro ritmo. Un proyecto pide otra manera. La Fluidez adaptativa escucha ese cambio y reconoce qué merece permanecer. Puedes ajustar el paso y seguir siendo fiel a lo que cuidas.","sourcePage":112,"originalTitle":"Fluidez adaptativa","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Adaptación de acuerdos, proyectos y maneras de actuar; no se atribuye a la fórmula una adaptación fisiológica."},{"id":"duelo_memoria","title":"Acompañar una pérdida que vuelve","description":"Quiero dar espacio al recuerdo de una pérdida y reconocer la compañía que necesito.","formulaId":"energy-r60-p715-c0440-f01","sourceRationale":"Cuando vuelve un duelo se refiere a la reaparición de una pérdida ante una fecha, un olor o una canción; invita a reconocer la memoria y respetar su tiempo.","sourceEvidence":"Lo que suele pasar. Una fecha, un olor o una canción y la pérdida está de nuevo aquí.\nDespués. Nombra en voz baja a quien extrañas. Si el duelo te sobrepasa, busca compañía.","sourcePage":715,"originalTitle":"Cuando vuelve un duelo","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Contexto específico de duelo que reaparece. La edición marca ACTIVAR · acogida y sostén; no propone depurar ni borrar el duelo."},{"id":"constancia_cuidada","title":"Continuar con paciencia y medida","description":"Quiero sostener lo que importa, reconociendo cuándo continuar, descansar o cambiar la manera.","formulaId":"energy-p158-f01","sourceRationale":"Perseverancia incluye continuidad, descanso, ayuda y revisión del método; no exige aguantar ni mantener una estrategia dañina.","sourceEvidence":"Hay obras que crecen gracias al regreso. Vuelves después de descansar, encuentras una dificultad y ajustas la manera. La Perseverancia conoce ese ritmo. Su compromiso incluye el cuidado de quien hace la obra.","sourcePage":152,"originalTitle":"Perseverancia","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Continuidad de una tarea o compromiso elegido, con posibilidad de pausa y adaptación; no se usa como exigencia de recuperación."},{"id":"reciprocidad","title":"Dar y recibir con libertad","description":"Quiero reconocer lo que puedo ofrecer, lo que necesito pedir y lo que no puedo sostener.","formulaId":"energy-p126-f01","sourceRationale":"Reciprocidad acompaña dar, recibir, pedir o rechazar con autonomía y medida, sin convertir el vínculo en una deuda.","sourceEvidence":"Un vínculo tiene espacio para dos experiencias. Puedes ofrecer algo valioso y escuchar que el otro necesita otra cosa. Puedes recibir sin desaparecer en una deuda. La Reciprocidad crece cuando cada persona puede decir con claridad lo que ofrece, lo que necesita y lo que no puede sostener.","sourcePage":118,"originalTitle":"Reciprocidad","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Intercambio dentro de un vínculo concreto, respetando consentimiento y diferencias."},{"id":"pertenencia","title":"Participar sin esconderme","description":"Quiero compartir un espacio sin ocultar lo que soy por miedo al rechazo.","formulaId":"energy-p097-f01","sourceRationale":"Pertenencia usa esta fórmula específicamente para el temor al rechazo al expresarse o cuando algo va bien; conserva cercanía y diferencia.","sourceEvidence":"En esta práctica vamos a mirar especialmente el temor a ser rechazado cuando te expresas o cuando algo te va bien. La fórmula elegida viene de ese contexto. Si tu experiencia es otra, puedes empezar con la tríada madre y la intención general de tener un lugar.","sourcePage":89,"originalTitle":"Pertenencia","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Mantener este alcance específico: temor al rechazo al expresarse o al tener éxito. No convertirla en una fórmula general para cualquier soledad."},{"id":"dignidad","title":"Reconocer mi valor sin demostrarlo","description":"Quiero tratarme con respeto sin medir mi valor por el rendimiento o la aprobación.","formulaId":"energy-p146-f01","sourceRationale":"Dignidad reconoce valor propio sin depender de comparación, rendimiento o aprobación inmediata.","sourceEvidence":"Puedes llegar a un día difícil y sentir que todo tu valor está en juego. Un trabajo que no salió, una respuesta que no llegó, una comparación que te hizo sentir pequeño. Detente un momento. La vida que eres sigue aquí. La Dignidad te permite presentarte con esa presencia, reconocer lo que puedes aportar y tratarte con el mismo respeto que le ofreces a cualquier otro ser humano.","sourcePage":140,"originalTitle":"Dignidad","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Valor y trato hacia uno mismo; no condiciona la dignidad a la salud, la productividad ni el resultado de una práctica."},{"id":"ecuanimidad","title":"Responder sin negar lo que siento","description":"Quiero dar espacio a una emoción y elegir una respuesta proporcionada.","formulaId":"energy-p327-f01","sourceRationale":"Ecuanimidad permite que la emoción participe sin decidirlo todo y propone una respuesta cuidadosa, proporcionada y reversible.","sourceEvidence":"Puedes sentir desagrado y conservar una respuesta cuidadosa. La Ecuanimidad no te pide volverte insensible; deja que la emoción participe sin que lo decida todo. Mira cuánto cambia una conversación cuando no necesitas expulsar enseguida la incomodidad.","sourcePage":321,"originalTitle":"Ecuanimidad","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Respuesta cotidiana ante agrado, incomodidad o incertidumbre; no promete eliminar emociones ni regular una condición clínica."},{"id":"integracion_cotidiana","title":"Llevar lo comprendido a la vida","description":"Quiero elegir una acción pequeña que exprese con coherencia lo que valoro.","formulaId":"energy-p701-f01","sourceRationale":"El protocolo invita a mirar la relación entre sentir, valorar, decir y hacer, y a elegir una corrección o acción concreta sin exigir resolverlo todo.","sourceEvidence":"Escribe cuatro frases breves: siento, valoro, digo y hago. Mira dónde hay una distancia que puedes atender. Después del código, une un valor con una acción pequeña que lo vuelva visible.","sourcePage":707,"originalTitle":"Dar cuerpo a lo que has comprendido · Trazo, meditación y acción","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Integración de una comprensión en una acción cotidiana; conservar el cierre de la práctica antes de llevar la acción a la relación o tarea."},{"id":"pedir_apoyo","title":"Pedir y recibir ayuda","description":"Quiero reconocer una ayuda disponible y recibirla conservando mi autonomía.","formulaId":"energy-p095-f01","sourceRationale":"La inteligencia Sostén trata de recibir cooperación y reconocer qué se necesita pedir sin entregar las propias decisiones.","sourceEvidence":"El Sostén reconoce la cooperación. Una silla recibe parte de tu peso; una persona puede escucharte; una decisión puede esperar hasta que tengas los recursos que necesitas. La vida encuentra continuidad cuando sabes con qué cuentas y qué necesitas pedir.","sourcePage":87,"originalTitle":"Sostén","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Sostén nombra aquí la capacidad humana de recibir apoyo; es distinto de Sostén como segunda posición de cualquier tríada."},{"id":"autoacogida","title":"Escuchar mi experiencia sin juzgarla","description":"Quiero dar espacio a algo que siento sin rechazarlo ni obedecer automáticamente cada impulso.","formulaId":"energy-p186-f01","sourceRationale":"Autoacogida propone recibir una parte de la experiencia con dignidad y mantener una respuesta responsable.","sourceEvidence":"Hay algo en ti que lleva tiempo esperando ser recibido. Quizás es cansancio. Quizás una rabia que te avergüenza, o una necesidad que aprendiste a esconder. Dale un lugar. La Autoacogida te permite escuchar esa parte sin convertirla en dueña de tu vida.","sourcePage":180,"originalTitle":"Autoacogida","sourceBook":"Códigos de Luz para tu Energía","sourceContext":"Acogida de la experiencia elegida por la persona; no interpreta esa experiencia como causa de una enfermedad ni como orden que deba obedecerse."}],"entries":[{"id":"acne","title":"Acné","category":"Piel","aliases":["espinillas","barros","granitos"],"definition":"Afección común de la piel en la que se obstruyen los folículos pilosos y aparecen granos. Puede afectar rostro, pecho, espalda y otras zonas, dejando a veces cicatrices.","source":{"title":"Acné","url":"https://medlineplus.gov/spanish/acne.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Ampliar la mirada sobre ti","reflection":"Puedes explorar qué lugar está teniendo tu apariencia en la forma de mirarte y relacionarte. La Llama invita a reconocer una presencia más amplia, donde también caben tu voz, tus capacidades, tus vínculos y las experiencias que deseas compartir.","questions":["¿Qué cualidad mía quisiera reconocer hoy?","¿Qué comentario sobre mi apariencia prefiero recibir de otra manera?","¿Qué encuentro deseo disfrutar siendo yo mismo?"],"phrase":"Puedo reconocer mi presencia completa y expresarme con libertad.","suggestedIntents":["dignidad","compasion","limites"],"editorialStatus":"propuesta_editorial"},{"id":"alergia-alimentaria","title":"Alergia alimentaria","category":"Alergias","aliases":["alergia a los alimentos","alergia a las comidas"],"definition":"Reacción del sistema inmunitario ante determinados alimentos que reconoce por error como perjudiciales. Sus manifestaciones pueden afectar distintas partes del cuerpo y variar en intensidad.","source":{"title":"Alergia a los alimentos","url":"https://medlineplus.gov/spanish/foodallergy.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Pertenecer conservando tu voz","reflection":"Los encuentros alrededor de la comida pueden abrir preguntas sobre pertenencia, comunicación y cuidado. Puedes contemplar la Llama como una presencia que acompaña tu derecho a expresar necesidades y participar de una manera que respete lo que has acordado para cuidarte.","questions":["¿Cómo quiero expresar mis necesidades en un encuentro compartido?","¿Qué me ayuda a sentirme incluido y respetado?","¿Qué conversación previa facilitaría mi participación?"],"phrase":"Puedo participar y expresar con claridad lo que necesito.","suggestedIntents":["expresion","limites","apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"alergia-estacional","title":"Alergia estacional","category":"Alergias","aliases":["rinitis alergica estacional","fiebre del heno","alergia al polen"],"definition":"Reacción alérgica a sustancias como el polen, presentes en ciertas épocas del año. Puede causar estornudos, congestión nasal y picazón de ojos, nariz o garganta.","source":{"title":"Rinitis alérgica","url":"https://medlineplus.gov/spanish/hayfever.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Atender lo pequeño que ocupa tu día","reflection":"A veces una molestia repetida ocupa más atención de la que otros perciben. Puedes reconocer qué aspectos de tu día se ven afectados y qué deseas comunicar. La Llama invita a una escucha amable de esas necesidades concretas, también cuando parecen pequeñas.","questions":["¿Qué momento de mi día se está haciendo más difícil?","¿Qué necesito explicar para que otros comprendan mi experiencia?","¿Qué gesto de amabilidad quiero ofrecerme hoy?"],"phrase":"Puedo escuchar mis necesidades cotidianas y darles un lugar.","suggestedIntents":["compasion","expresion","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"alopecia-areata","title":"Alopecia areata","category":"Piel y cabello","aliases":["alopecia en placas","alopecia autoinmune"],"definition":"Afección autoinmunitaria que puede provocar pérdida de cabello en áreas redondas y, en ocasiones, más extensas. Puede afectar el cuero cabelludo y otras zonas del cuerpo.","source":{"title":"Alopecia areata","url":"https://medlineplus.gov/spanish/ency/article/001450.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer lo que cambia y lo que permanece","reflection":"Los cambios en el cabello pueden despertar sentimientos distintos en cada persona. Puedes escucharlos con libertad, sin apresurarte a adoptar una actitud particular. La Llama ofrece una imagen de continuidad interior desde la cual reconocer tu identidad y elegir cómo quieres presentarte.","questions":["¿Qué siento al mirar este cambio?","¿Qué aspectos de mi identidad quiero reconocer hoy?","¿Cómo deseo presentarme y qué apoyo facilitaría esa elección?"],"phrase":"Puedo dar lugar a mis sentimientos y elegir cómo me presento.","suggestedIntents":["dignidad","tristeza","autoacogida"],"editorialStatus":"propuesta_editorial"},{"id":"anemia-ferropenica","title":"Anemia ferropénica","category":"Sangre","aliases":["anemia por deficiencia de hierro","anemia por falta de hierro"],"definition":"Tipo de anemia relacionado con una cantidad insuficiente de hierro para producir hemoglobina. Puede reducir el transporte de oxígeno y acompañarse de cansancio, debilidad o palidez.","source":{"title":"Anemia ferropénica","url":"https://medlineplus.gov/spanish/ency/article/000584.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer la energía disponible","reflection":"Si el cansancio modifica lo que puedes hacer, puedes reconocerlo sin medir tu valor por la productividad. La imagen de la Llama acompaña una presencia que merece escucha. Pregúntate qué necesitas ajustar, qué puedes compartir y qué expectativas quisieras revisar con amabilidad.","questions":["¿Qué tarea me está costando más de lo habitual?","¿Qué expectativa puedo revisar por ahora?","¿Quién podría ayudarme con algo concreto?"],"phrase":"Mi valor permanece y puedo reconocer la energía disponible hoy.","suggestedIntents":["descanso","compasion","apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"anemia-perniciosa","title":"Anemia perniciosa","category":"Sangre","aliases":["anemia por falta de factor intrinseco","anemia de Biermer"],"definition":"Anemia por déficit de vitamina B12 asociado a una absorción inadecuada, generalmente por falta de factor intrínseco. Puede afectar la formación de glóbulos rojos y el sistema nervioso.","source":{"title":"Anemia perniciosa","url":"https://medlineplus.gov/spanish/ency/article/000569.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Hacer espacio para comprender","reflection":"Aprender el nombre de una condición puede traer alivio, dudas o sentimientos mezclados. Puedes recibirlos con tiempo. La Llama puede acompañar una búsqueda de comprensión: organizar lo que deseas preguntar y reconocer cómo quieres participar en los cuidados que se incorporan a tu vida.","questions":["¿Qué cambió para mí al conocer este diagnóstico?","¿Qué información necesito recibir con palabras más claras?","¿Qué me ayudaría a integrar mis cuidados en la vida cotidiana?"],"phrase":"Puedo aprender a mi ritmo y expresar lo que necesito comprender.","suggestedIntents":["claridad","expresion","apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"anorexia-nerviosa","title":"Anorexia nerviosa","category":"Conducta alimentaria","aliases":["anorexia nerviosa"],"definition":"Trastorno alimentario que implica restricción de la ingesta, miedo intenso a aumentar de peso y alteraciones en la percepción corporal. Puede comprometer gravemente la salud física y emocional.","source":{"title":"Anorexia","url":"https://medlineplus.gov/spanish/ency/article/000362.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Recibir cuidado con dignidad","reflection":"Puedes acercarte a esta reflexión desde la dignidad de tu vida y la posibilidad de recibir compañía. La Llama puede simbolizar una presencia amable, atenta a quien eres en tus vínculos, tus intereses y tus deseos. Elige una pregunta que puedas compartir con tu equipo de apoyo.","questions":["¿Qué cualidad mía quisiera reconocer más allá de mi apariencia?","¿Qué forma de compañía me ayuda a hablar con honestidad?","¿Qué necesidad quiero expresar a quienes participan en mi cuidado?"],"phrase":"Mi vida merece cuidado, escucha y compañía.","suggestedIntents":["dignidad","compasion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"apnea-obstructiva-sueno","title":"Apnea obstructiva del sueño","category":"Sueño","aliases":["apnea del sueño","apnea obstructiva","AOS","SAOS"],"definition":"Trastorno en el que la vía respiratoria se estrecha o se bloquea repetidamente durante el sueño, interrumpiendo la respiración y fragmentando el descanso nocturno.","reflectionHeading":"Recibir apoyo para descansar","reflection":"Si esta experiencia te hace sentir frustración al despertar, puedes reconocer ese cansancio sin juzgarte por él. En el lenguaje de la Llama, recibir cuidado puede ser una expresión de dignidad. La contemplación acompaña cómo atraviesas la noche y el día, sin sustituir tu atención clínica.","questions":["¿Qué pesa más hoy: el cansancio, la preocupación o sentir que otros no comprenden?","¿Qué ayuda concreta te permitiría vivir el descanso con menos soledad?","¿Qué exigencia cotidiana puedes conversar con alguien de confianza?"],"phrase":"Mi necesidad de descanso merece comprensión y cuidado.","suggestedIntents":["descanso","pedir_apoyo","compasion"],"source":{"title":"Apnea del sueño","url":"https://medlineplus.gov/spanish/sleepapnea.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"artritis-psoriasica","title":"Artritis psoriásica","category":"Movimiento y articulaciones","aliases":["artritis psoriasica","psoriasis artritica","artropatia psoriasica"],"definition":"Enfermedad inflamatoria articular asociada con psoriasis que puede causar dolor, rigidez e hinchazón. Los síntomas de la piel y de las articulaciones pueden aparecer en momentos distintos.","source":{"title":"Artritis psoriásica","url":"https://medlineplus.gov/spanish/psoriaticarthritis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer las distintas partes de tu experiencia","reflection":"Puedes dar espacio a lo que cambia en tus actividades y a lo que sientes respecto de tu imagen. La Llama puede acompañar ambas experiencias con una misma presencia amable, desde la cual elegir qué necesidad quieres expresar y qué apoyo deseas recibir.","questions":["¿Qué aspecto de mi experiencia necesita escucha hoy?","¿Qué actividad quisiera seguir compartiendo con otras personas?","¿Qué ayuda concreta podría facilitar ese encuentro?"],"phrase":"Puedo recibir mi experiencia completa y dar voz a lo que necesito.","suggestedIntents":["autoacogida","adaptacion","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"artritis-reumatoide","title":"Artritis reumatoide","category":"Movimiento y articulaciones","aliases":["AR","artritis reumatoidea","reuma"],"definition":"Enfermedad autoinmune que provoca inflamación, dolor y rigidez en las articulaciones. Puede afectar también otros tejidos y órganos; se diferencia de la artrosis.","source":{"title":"Artritis reumatoide","url":"https://medlineplus.gov/spanish/rheumatoidarthritis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Escucharte en los días distintos","reflection":"Si tus posibilidades cambian entre un día y otro, puedes reconocer lo que cada momento pide. La Llama acompaña una relación paciente contigo: dar espacio a tus emociones, expresar tus límites y recibir compañía.","questions":["¿Cómo estoy viviendo los cambios de mi día a día?","¿Qué quiero comunicar cuando necesito ajustar un compromiso?","¿Quién puede escucharme sin pedirme que explique todo?"],"phrase":"Puedo escuchar el día que estoy viviendo y acompañarme con respeto.","editorialStatus":"propuesta_editorial","suggestedIntents":["adaptacion","limites","autoacogida"]},{"id":"artrosis","title":"Artrosis","category":"Movimiento y articulaciones","aliases":["osteoartritis","artrosis de rodilla","artrosis de cadera"],"definition":"Afección de las articulaciones en la que se deteriora el cartílago que facilita su movimiento. Puede producir dolor, rigidez y dificultad para mover la articulación afectada.","source":{"title":"Osteoartritis","url":"https://medlineplus.gov/spanish/osteoarthritis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar lugar a nuevas formas de participar","reflection":"Puedes mirar qué actividades tienen significado para ti y cómo deseas seguir participando en ellas. En esta reflexión, la Llama acompaña la continuidad de tu presencia, tus vínculos y tu capacidad de elegir.","questions":["¿Qué actividad me conecta con algo que amo?","¿Qué adaptación o ayuda quisiera conversar?","¿Cómo puedo reconocer lo que sí está disponible hoy?"],"phrase":"Mi presencia conserva valor en cada forma de participar.","editorialStatus":"propuesta_editorial","suggestedIntents":["adaptacion","dignidad","pedir_apoyo"]},{"id":"asma","title":"Asma","category":"Salud respiratoria","aliases":["asma bronquial","asma alergica"],"definition":"Enfermedad crónica en la que las vías respiratorias pueden inflamarse y estrecharse, provocando episodios de tos, silbidos al respirar y opresión en el pecho.","source":{"title":"Asma","url":"https://medlineplus.gov/spanish/asthma.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Encontrar compañía interior","reflection":"En un momento de reposo cómodo, puedes contemplar la Llama como una imagen de compañía. Deja que tu atención reconozca los apoyos de tu entorno y las palabras que te gustaría compartir con alguien de confianza.","questions":["¿Qué me hace sentir acompañado en mi vida cotidiana?","¿Qué quiero que otra persona sepa sobre lo que estoy viviendo?","¿Qué intención me gustaría llevar a un momento tranquilo?"],"phrase":"Puedo recibir compañía y expresar lo que necesito.","editorialStatus":"propuesta_editorial","suggestedIntents":["apoyo","expresion","confianza_discernida"]},{"id":"bronquiectasias","title":"Bronquiectasias","category":"Salud respiratoria","aliases":["bronquiectasia","dilatacion bronquial"],"definition":"Daño de las vías respiratorias que provoca su ensanchamiento permanente. Puede acompañarse de tos persistente con mucosidad, infecciones respiratorias repetidas, cansancio y dificultad para respirar.","source":{"title":"Bronquiectasia","url":"https://medlineplus.gov/spanish/ency/article/000144.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar lugar al cuidado que se repite","reflection":"Cuando el cuidado ocupa un lugar habitual en tu jornada, también puedes preguntarte por tus deseos, tus relaciones y tus pequeños disfrutes. La Llama invita a reconocer la persona completa que participa en esas rutinas y la compañía que quisiera recibir.","questions":["¿Qué momento del día quiero reservar para algo que me importa?","¿Qué parte de mi rutina quisiera compartir o explicar?","¿Qué apoyo me permite sentirme acompañado con respeto?"],"phrase":"Mi vida tiene espacio para el cuidado, los vínculos y lo que amo.","suggestedIntents":["constancia_cuidada","pedir_apoyo","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"bulimia-nerviosa","title":"Bulimia nerviosa","category":"Conducta alimentaria","aliases":["bulimia"],"definition":"Trastorno alimentario caracterizado por episodios repetidos de atracón y conductas compensatorias posteriores. Puede afectar la salud física y acompañarse de preocupación intensa por el peso o la figura.","source":{"title":"Bulimia","url":"https://medlineplus.gov/spanish/ency/article/000341.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar palabras a lo que cuesta compartir","reflection":"Si hay una parte de tu experiencia que cuesta contar, puedes empezar por una frase sencilla. La Llama puede ser una imagen de acogida mientras reconoces a quién deseas acercarte. Tu reflexión puede centrarse en recibir apoyo y hablar de lo que necesitas con respeto.","questions":["¿Qué quisiera poder contar sin sentirme juzgado?","¿Quién puede ofrecerme una escucha cuidadosa?","¿Qué petición concreta quisiera llevar a mi equipo de apoyo?"],"phrase":"Puedo compartir mi experiencia y recibir un trato digno.","suggestedIntents":["expresion","compasion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"cataratas","title":"Cataratas","category":"Visión","aliases":["catarata","opacidad del cristalino"],"definition":"Opacidad del cristalino, la lente interna del ojo, que dificulta el paso de la luz. Puede provocar visión borrosa, deslumbramiento o dificultad para distinguir detalles.","reflectionHeading":"Mantener tu participación en lo cotidiano","reflection":"Cuando ver ciertos detalles se vuelve difícil, puede cambiar tu manera de leer, desplazarte o disfrutar encuentros. Puedes explorar qué actividades quieres seguir compartiendo y qué ayuda prefieres. En el marco de la Llama, la contemplación puede apoyarse en palabras o compañía, sin necesitar imágenes nítidas.","questions":["¿Qué actividad te importa conservar o adaptar?","¿Cómo prefieres que te ofrezcan ayuda?","¿Qué forma de contemplación te resulta accesible sin esforzar la vista?"],"phrase":"Mi participación importa y puedo pedir que el entorno me incluya.","suggestedIntents":["adaptacion","pedir_apoyo","expresion"],"source":{"title":"Cataratas","url":"https://medlineplus.gov/spanish/cataract.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"cefalea-tensional","title":"Cefalea tensional","category":"Neurología","aliases":["dolor de cabeza tensional","cefalea por tension","dolor de cabeza"],"definition":"Tipo frecuente de dolor de cabeza que suele sentirse como presión o una banda apretada. Puede acompañarse de sensibilidad en músculos del cuello o del cuero cabelludo.","source":{"title":"Cefalea tensional","url":"https://medlineplus.gov/spanish/ency/article/000797.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Escuchar el momento presente","reflection":"Puedes hacer espacio para observar cómo estás viviendo este momento. La imagen de la Llama acompaña una escucha abierta: reconocer lo que sientes, nombrar una necesidad y elegir qué deseas llevar a la práctica.","questions":["¿Qué noto en mi ánimo en este momento?","¿Qué necesito expresar con palabras sencillas?","¿Qué actividad o conversación puedo organizar de otra manera?"],"phrase":"Me doy un momento para escuchar y elegir con claridad.","editorialStatus":"propuesta_editorial","suggestedIntents":["autoacogida","expresion","eleccion_consciente"]},{"id":"cirrosis","title":"Cirrosis","category":"Salud hepática","aliases":["cirrosis hepatica","fibrosis hepatica avanzada"],"definition":"Cicatrización extensa del hígado que aparece tras lesiones o enfermedades prolongadas. El tejido cicatricial sustituye tejido sano y dificulta que el órgano cumpla sus funciones.","source":{"title":"Cirrosis","url":"https://medlineplus.gov/spanish/cirrhosis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Conservar tu voz en el cuidado","reflection":"Cuando tu salud ocupa más espacio en la vida cotidiana, puedes reconocer qué decisiones, vínculos y deseos siguen siendo importantes para ti. La Llama puede acompañar esa presencia propia, ayudándote a formular las preguntas y preferencias que quieras compartir.","questions":["¿Qué deseo que se tenga en cuenta al acompañarme?","¿Qué ayuda quiero recibir y cómo prefiero pedirla?","¿Qué vínculo o actividad conserva un significado especial para mí?"],"phrase":"Mi voz y mis preferencias pueden estar presentes en mi cuidado.","suggestedIntents":["expresion","pedir_apoyo","limites"],"editorialStatus":"propuesta_editorial"},{"id":"cistitis-intersticial","title":"Cistitis intersticial","category":"Salud renal y urinaria","aliases":["sindrome de vejiga dolorosa","dolor vesical cronico"],"definition":"Afección persistente que puede causar dolor o incomodidad en la vejiga y necesidad frecuente o urgente de orinar. La intensidad y combinación de síntomas varían entre personas.","source":{"title":"Cistitis intersticial","url":"https://medlineplus.gov/spanish/interstitialcystitis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar palabras a una experiencia persistente","reflection":"Si te resulta difícil explicar lo que estás viviendo, puedes empezar por una necesidad concreta de hoy. En la contemplación, la Llama ofrece una imagen de reconocimiento interior: recibir tu experiencia y elegir qué deseas comunicar sobre tus actividades, vínculos o intimidad.","questions":["¿Qué aspecto de mi experiencia está siendo difícil de explicar?","¿Qué necesito conversar sobre mis actividades o mi intimidad?","¿Quién podría acompañarme escuchando lo que yo considero importante?"],"phrase":"Mi experiencia puede encontrar palabras y una compañía que la respete.","suggestedIntents":["expresion","autoacogida","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"colesterol-alto","title":"Colesterol alto","category":"Salud metabólica","aliases":["hipercolesterolemia","LDL alto","colesterol elevado"],"definition":"Elevación de ciertos lípidos en la sangre, especialmente del colesterol LDL. Su exceso puede favorecer la acumulación de placa en las arterias y aumentar el riesgo cardiovascular.","source":{"title":"Colesterol","url":"https://medlineplus.gov/spanish/cholesterol.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar sentido a la continuidad","reflection":"Un resultado de laboratorio puede abrir preguntas sobre el futuro y el cuidado cotidiano. Puedes acercarte a esas preguntas con curiosidad. En la visión de la Llama, una intención puede encontrar expresión en acuerdos pequeños que eliges comprender y sostener con apoyo.","questions":["¿Qué quiero comprender de mis resultados?","¿Qué hace más fácil sostener mis acuerdos de cuidado?","¿Qué apoyo puedo pedir para organizarme?"],"phrase":"Puedo comprender mi cuidado y sostenerlo con pasos elegidos.","suggestedIntents":["constancia_cuidada","integracion_cotidiana","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"colitis-ulcerosa","title":"Colitis ulcerosa","category":"Salud digestiva","aliases":["colitis ulcerativa","rectocolitis ulcerosa"],"definition":"Enfermedad inflamatoria intestinal que produce inflamación y úlceras en el revestimiento del colon y del recto. Puede causar diarrea, sangrado y dolor abdominal.","source":{"title":"Colitis ulcerativa","url":"https://medlineplus.gov/spanish/ulcerativecolitis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Conservar intimidad y compañía","reflection":"Puedes elegir qué parte de tu experiencia quieres compartir y qué parte deseas reservarte. La contemplación de la Llama ofrece una imagen de acogida: escuchar lo que necesitas, reconocer tu intimidad y abrir conversaciones con personas que puedan acompañarte con respeto.","questions":["¿Qué necesito que comprendan sobre mi día a día?","¿Qué prefiero compartir y qué quiero mantener privado?","¿Qué ayuda concreta facilitaría una actividad importante para mí?"],"phrase":"Mi intimidad y mi necesidad de compañía pueden tener espacio juntas.","suggestedIntents":["limites","confianza_discernida","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"covid-persistente","title":"COVID persistente","category":"Condiciones posinfecciosas","aliases":["COVID prolongado","long COVID","afecciones posteriores al COVID-19"],"definition":"Conjunto de problemas de salud que continúan o aparecen después de una infección por coronavirus. Puede incluir fatiga, dificultades cognitivas y otros síntomas que fluctúan.","source":{"title":"Afecciones posteriores al COVID-19 (COVID-19 persistente)","url":"https://medlineplus.gov/spanish/postcovidconditionslongcovid.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer una experiencia cambiante","reflection":"Si tus posibilidades fluctúan, puedes encontrar palabras para describir el día que realmente estás viviendo. La Llama puede acompañarte como imagen de reconocimiento, dando lugar a tu experiencia y a la necesidad de ser escuchado sin tener que demostrar tu esfuerzo.","questions":["¿Qué ha cambiado hoy respecto de otros días?","¿Qué necesito que comprendan sobre mis posibilidades actuales?","¿Quién puede acompañarme a expresar una necesidad concreta?"],"phrase":"Mi experiencia merece escucha, también cuando cambia.","suggestedIntents":["dignidad","adaptacion","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"calculos-biliares","title":"Cálculos biliares","category":"Salud digestiva","aliases":["piedras en la vesicula","colelitiasis","litiasis biliar"],"definition":"Depósitos sólidos que se forman cuando ciertas sustancias de la bilis se endurecen. Pueden permanecer sin síntomas o bloquear los conductos por donde circula la bilis.","source":{"title":"Cálculos biliares","url":"https://medlineplus.gov/spanish/gallstones.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Hacer espacio para comprender","reflection":"Una noticia sobre tu salud puede traer inquietud, preguntas o deseos de reorganizar tus planes. Puedes contemplar la Llama como una compañía mientras distingues qué sabes, qué necesitas preguntar y qué decisión requiere todavía tiempo para ser comprendida.","questions":["¿Qué siento al pensar en esta situación?","¿Qué información tengo y qué quiero preguntar?","¿Quién podría acompañarme en una conversación que me importa?"],"phrase":"Puedo dar tiempo a mis preguntas y recibir compañía para comprender.","suggestedIntents":["claridad","incertidumbre","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"calculos-renales","title":"Cálculos renales","category":"Salud renal y urinaria","aliases":["piedras en los rinones","litiasis renal","nefrolitiasis"],"definition":"Formaciones sólidas que se originan en los riñones a partir de sustancias presentes en la orina. Pueden desplazarse por las vías urinarias y causar obstrucción o dolor.","source":{"title":"Piedras en los riñones","url":"https://medlineplus.gov/spanish/kidneystones.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Escuchar tus necesidades en la interrupción","reflection":"Cuando una experiencia corporal interrumpe tus actividades, puedes explorar qué necesitas para sentirte acompañado. La Llama puede ser una imagen de cercanía interior mientras reconoces tus emociones, formulas una pregunta y decides qué ayuda práctica quieres pedir a quienes están disponibles.","questions":["¿Qué necesito que alguien comprenda de este momento?","¿Qué pregunta me ayudaría a ordenar mi inquietud?","¿Qué tarea o compromiso puedo compartir con otra persona?"],"phrase":"Puedo nombrar lo que necesito y permitir que me acompañen.","suggestedIntents":["apoyo","claridad","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"cancer","title":"Cáncer","category":"Acompañamiento oncológico","aliases":["cancer","proceso oncologico","diagnostico oncologico"],"definition":"Nombre de un conjunto de enfermedades en las que ciertas células se multiplican de manera descontrolada y pueden invadir otros tejidos o propagarse a distintas partes del cuerpo.","source":{"title":"Cáncer","url":"https://medlineplus.gov/spanish/cancer.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Recibir compañía en tu propio camino","reflection":"Cada persona vive este proceso de una manera singular. Puedes hacer espacio para las emociones que aparezcan y para los vínculos que deseas cerca. En la contemplación, la Llama puede representar una compañía que permanece contigo también en la incertidumbre.","questions":["¿Qué siento hoy y con quién quisiera compartirlo?","¿Qué compañía deseo recibir y qué espacio necesito reservarme?","¿Qué pregunta o deseo quiero expresar a quienes me acompañan en mi cuidado?"],"phrase":"Puedo recibir compañía siendo fiel a lo que siento hoy.","editorialStatus":"propuesta_editorial","suggestedIntents":["autoacogida","pedir_apoyo","incertidumbre"]},{"id":"cancer-colorrectal","title":"Cáncer colorrectal","category":"Acompañamiento oncológico","aliases":["cancer de colon","cancer de recto","cancer del colon y del recto"],"definition":"Cáncer que se origina en los tejidos del colon o del recto, partes del intestino grueso. Las células alteradas pueden crecer e invadir otros tejidos.","source":{"title":"Cáncer del colon y del recto","url":"https://medlineplus.gov/spanish/colorectalcancer.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Conservar tu voz en lo cotidiano","reflection":"Cuando un proceso de salud ocupa tiempo y atención, puedes explorar qué aspectos cotidianos deseas cuidar especialmente. La Llama puede ofrecer una imagen de continuidad personal. Puedes reconocer tu necesidad de privacidad, preparar una conversación y pedir una ayuda que se ajuste a tu vida.","questions":["¿Qué parte de mi rutina quisiera conversar con más detalle?","¿Cómo prefiero que se respete mi privacidad?","¿Qué apoyo me permitiría dedicar tiempo a algo que valoro?"],"phrase":"Puedo cuidar mi privacidad y participar en las decisiones de mi día.","suggestedIntents":["limites","adaptacion","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"cancer-cuello-uterino","title":"Cáncer de cuello uterino","category":"Acompañamiento oncológico","aliases":["cancer cervical","cancer de cervix"],"definition":"Cáncer que comienza en las células del cuello uterino, la parte inferior del útero. Suele desarrollarse gradualmente a partir de cambios celulares que pueden volverse invasivos.","source":{"title":"Cáncer de cuello uterino","url":"https://medlineplus.gov/spanish/cervicalcancer.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer tu voz y tu intimidad","reflection":"Puedes explorar qué información quieres compartir y qué deseas reservar para conversaciones de confianza. La Llama puede acompañar una presencia interior que reconoce tu dignidad. Tus preguntas sobre la vida cotidiana, la intimidad o el futuro pueden encontrar un lugar sin apresurar las respuestas.","questions":["¿Qué quiero comprender con mayor claridad?","¿Con quién puedo hablar de mi intimidad con confianza?","¿Qué deseo que quienes me acompañan tengan presente?"],"phrase":"Mi dignidad y mi voz permanecen presentes en este proceso.","suggestedIntents":["limites","confianza_discernida","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"cancer-mama","title":"Cáncer de mama","category":"Acompañamiento oncológico","aliases":["cancer de seno","cancer mamario"],"definition":"Enfermedad en la que células del tejido mamario crecen sin control. Existen distintos tipos, que pueden permanecer localizados o extenderse a tejidos cercanos y otras partes del cuerpo.","source":{"title":"Cáncer de seno","url":"https://medlineplus.gov/spanish/breastcancer.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Elegir cómo recibir cercanía","reflection":"Puedes preguntarte qué cercanía deseas y qué espacio quieres conservar durante este proceso. La Llama puede representar una compañía que reconoce tu voz y tu intimidad. Cada persona vive su cuerpo, sus vínculos y sus decisiones de una manera propia; tu reflexión puede partir de ahí.","questions":["¿Qué compañía deseo recibir hoy?","¿Qué aspecto de mi intimidad quiero cuidar?","¿Qué pregunta quisiera preparar para mi próxima conversación de cuidado?"],"phrase":"Puedo elegir la cercanía y el espacio que necesito.","suggestedIntents":["limites","pedir_apoyo","autoacogida"],"editorialStatus":"propuesta_editorial"},{"id":"cancer-prostata","title":"Cáncer de próstata","category":"Acompañamiento oncológico","aliases":["cancer prostatico"],"definition":"Cáncer que comienza en las células de la próstata. Su comportamiento varía: algunos crecen lentamente y otros pueden avanzar o extenderse a otras zonas del organismo.","source":{"title":"Cáncer de próstata","url":"https://medlineplus.gov/spanish/prostatecancer.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Abrir una conversación a tu medida","reflection":"Puedes dar espacio a preguntas que quizá resultan personales o difíciles de expresar. La Llama puede acompañarte como una imagen de escucha respetuosa. Tu manera de vivir la intimidad, los vínculos y los cambios cotidianos merece palabras propias y personas que sepan recibirlas.","questions":["¿Qué pregunta he estado dejando para después?","¿Con quién quisiera hablar de mis preocupaciones personales?","¿Qué forma de ayuda práctica sería bienvenida?"],"phrase":"Mis preguntas personales merecen una conversación respetuosa.","suggestedIntents":["expresion","confianza_discernida","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"cancer-pulmon","title":"Cáncer de pulmón","category":"Acompañamiento oncológico","aliases":["cancer pulmonar","carcinoma broncopulmonar"],"definition":"Cáncer que se forma en los tejidos pulmonares, generalmente en las células que recubren las vías respiratorias. Sus principales grupos son de células pequeñas y no pequeñas.","source":{"title":"Cáncer de pulmón","url":"https://medlineplus.gov/spanish/lungcancer.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Recibir compañía sin tener que explicarlo todo","reflection":"Puedes elegir cómo deseas ser escuchado durante este proceso. La imagen de la Llama puede representar una compañía que reconoce a la persona completa, con su historia, sus vínculos y sus deseos. Quizás hoy quieras compartir una emoción o pedir una presencia sencilla y cercana.","questions":["¿Qué emoción quisiera compartir hoy?","¿Qué comentario preferiría recibir de otra manera?","¿Qué tipo de compañía me resulta valiosa en este momento?"],"phrase":"Merezco una compañía que me reciba con respeto.","suggestedIntents":["dignidad","compasion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"degeneracion-macular","title":"Degeneración macular","category":"Visión","aliases":["degeneracion de la macula","DMAE","degeneracion macular relacionada con la edad"],"definition":"Enfermedad que afecta la mácula, zona de la retina responsable de la visión central detallada. Puede dificultar reconocer rostros, leer y distinguir detalles de los objetos.","reflectionHeading":"Seguir encontrando formas de conexión","reflection":"Los cambios en la visión central pueden tocar actividades queridas y maneras de relacionarte. Hay espacio para extrañar lo que cambia y para elegir otras formas de encuentro. La Llama puede evocarse mediante una palabra o una intención compartida; no necesitas verla mentalmente para participar.","questions":["¿Qué actividad o encuentro echas de menos y quisieras adaptar?","¿Qué otras formas de contacto te resultan valiosas?","¿Qué emoción sobre estos cambios necesita ser escuchada sin apresurarla?"],"phrase":"Puedo buscar nuevas formas de conexión sin negar lo que extraño.","suggestedIntents":["tristeza","adaptacion","expresion"],"source":{"title":"Degeneración macular","url":"https://medlineplus.gov/spanish/maculardegeneration.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"depresion","title":"Depresión","category":"Salud mental","aliases":["trastorno depresivo","depresion mayor"],"definition":"Trastorno del estado de ánimo que afecta de forma persistente los sentimientos, el pensamiento y las actividades. Puede incluir pérdida de interés, cambios de sueño y dificultades cotidianas.","source":{"title":"Depresión","url":"https://medlineplus.gov/spanish/depression.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar lugar a tu experiencia sin exigirte una emoción","reflection":"Puedes reconocer cómo es este día para ti, incluso cuando cuesta encontrar palabras o interés. Si te resulta amable, la Llama puede representar una compañía discreta. Una pregunta breve o el contacto con alguien de confianza pueden ser el centro de tu reflexión de hoy.","questions":["¿Cómo podría describir este día con mis propias palabras?","¿Quién puede escucharme con paciencia?","¿Qué ayuda concreta sería valiosa hoy?"],"phrase":"Mi experiencia merece escucha también en los días difíciles.","suggestedIntents":["autoacogida","compasion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"dermatitis-atopica","title":"Dermatitis atópica","category":"Piel","aliases":["eccema atopico","eczema atopico","eccema","eczema"],"definition":"Forma frecuente de eccema que causa piel seca, picazón e irritación. Es común en la infancia, también afecta a adultos y puede alternar períodos de mejoría y empeoramiento.","source":{"title":"Eccema","url":"https://medlineplus.gov/spanish/eczema.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Relacionarte contigo con ternura","reflection":"Puedes explorar cómo te sientes en tu vida cotidiana y en el encuentro con otras personas. La imagen de la Llama invita a una mirada amable, que reconoce tu dignidad y deja espacio para expresar tus preferencias.","questions":["¿Cómo me gustaría que me acompañaran cuando estoy incómodo?","¿Qué comentarios o preguntas prefiero recibir de otra manera?","¿Qué cualidad mía quiero reconocer más allá de mi apariencia?"],"phrase":"Mi dignidad y mi voz tienen un lugar en cada encuentro.","editorialStatus":"propuesta_editorial","suggestedIntents":["dignidad","compasion","limites"]},{"id":"diabetes-gestacional","title":"Diabetes gestacional","category":"Salud metabólica","aliases":["diabetes del embarazo","diabetes durante el embarazo"],"definition":"Diabetes que aparece durante el embarazo cuando la producción de insulina no cubre las necesidades adicionales del organismo. Se manifiesta por niveles elevados de glucosa en la sangre.","source":{"title":"Diabetes y el embarazo","url":"https://medlineplus.gov/spanish/diabetesandpregnancy.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Recibir compañía en una etapa de cambios","reflection":"Durante el embarazo puedes vivir emociones distintas mientras incorporas nuevos cuidados. Date permiso para reconocerlas con tus propias palabras. La Llama puede acompañar un espacio de ternura donde expresar preguntas, compartir tareas y escuchar qué forma de apoyo deseas recibir en esta etapa.","questions":["¿Qué emoción necesita hoy un espacio de escucha?","¿Qué pregunta quiero llevar a mi próxima consulta?","¿Qué tarea o preocupación me gustaría compartir?"],"phrase":"Puedo vivir esta etapa con ternura, preguntas y compañía.","suggestedIntents":["adaptacion","pedir_apoyo","compasion"],"editorialStatus":"propuesta_editorial"},{"id":"diabetes-tipo-1","title":"Diabetes tipo 1","category":"Salud metabólica","aliases":["diabetes tipo uno","diabetes insulinodependiente","diabetes juvenil"],"definition":"Enfermedad en la que el organismo produce poca o ninguna insulina, habitualmente por destrucción autoinmune de las células que la fabrican. La glucosa se acumula en la sangre.","source":{"title":"Diabetes tipo 1","url":"https://medlineplus.gov/spanish/diabetestype1.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Cuidarte sin perder tu propia vida","reflection":"Las decisiones de cuidado pueden ocupar mucho espacio en el día. Puedes explorar cómo deseas compartir esa responsabilidad y conservar tiempo para lo que disfrutas. La Llama acompaña una presencia completa: tus proyectos, tus vínculos y tus necesidades también merecen atención.","questions":["¿Qué parte de mi cuidado quisiera compartir o explicar mejor?","¿Qué actividad me conecta con el disfrute?","¿Qué necesito que los demás respeten de mis decisiones?"],"phrase":"Mi cuidado puede convivir con mis proyectos y mi propia voz.","suggestedIntents":["constancia_cuidada","limites","reciprocidad"],"editorialStatus":"propuesta_editorial"},{"id":"diabetes-tipo-2","title":"Diabetes tipo 2","category":"Salud metabólica","aliases":["diabetes tipo dos","diabetes mellitus tipo 2","glucosa elevada"],"definition":"Enfermedad en la que la glucosa permanece demasiado elevada en la sangre porque el organismo utiliza mal la insulina o no produce suficiente para sus necesidades.","source":{"title":"Diabetes tipo 2","url":"https://medlineplus.gov/spanish/diabetestype2.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Cuidarte con dignidad","reflection":"Las rutinas de cuidado pueden formar parte de tu vida de maneras distintas. Puedes explorar cómo te relacionas con ellas y qué apoyo deseas. En el lenguaje de la Llama, cada gesto consciente es una oportunidad para participar en tu vida con dignidad.","questions":["¿Qué parte de mi cuidado estoy pudiendo sostener?","¿Dónde me vendría bien recibir ayuda práctica?","¿Cómo quiero hablarme cuando un día resulta difícil?"],"phrase":"Mi cuidado puede crecer con paciencia, dignidad y compañía.","editorialStatus":"propuesta_editorial","suggestedIntents":["dignidad","constancia_cuidada","pedir_apoyo"]},{"id":"diverticulitis","title":"Diverticulitis","category":"Salud digestiva","aliases":["inflamacion de diverticulos","diverticulitis del colon"],"definition":"Inflamación de una o varias pequeñas bolsas que pueden formarse en la pared del colon. Puede aparecer repentinamente y causar molestias abdominales u otras complicaciones.","source":{"title":"Diverticulosis y diverticulitis","url":"https://medlineplus.gov/spanish/diverticulosisanddiverticulitis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reorganizar el día con compañía","reflection":"Si una situación de salud cambia tus planes, puedes reconocer la frustración, el cansancio o las preguntas que aparezcan. En la contemplación de la Llama encuentras una imagen para estar contigo y elegir qué apoyos necesitas en esta reorganización cotidiana.","questions":["¿Qué cambió en mi día y cómo lo estoy viviendo?","¿Qué compromiso quiero conversar o reorganizar?","¿Qué ayuda concreta podría hacer más llevadero este momento?"],"phrase":"Puedo reorganizar mis planes y dar espacio al apoyo disponible.","suggestedIntents":["adaptacion","pedir_apoyo","descanso"],"editorialStatus":"propuesta_editorial"},{"id":"dolor-lumbar","title":"Dolor lumbar","category":"Movimiento y articulaciones","aliases":["lumbalgia","dolor de espalda baja","dolor lumbar cronico"],"definition":"Dolor situado en la zona baja de la espalda, entre las costillas inferiores y los glúteos. Puede ser breve o persistente y limitar el movimiento cotidiano.","source":{"title":"Lumbalgia","url":"https://www.who.int/es/news-room/fact-sheets/detail/low-back-pain","organization":"Organización Mundial de la Salud","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer los apoyos disponibles","reflection":"Si el dolor modifica tu manera de participar en el día, puedes explorar qué ayudas te resultan valiosas. La Llama puede simbolizar una presencia que acompaña tu vida concreta, incluidas tus decisiones sobre tiempo, compañía y actividades.","questions":["¿Qué actividad está siendo más difícil de sostener?","¿Qué ayuda concreta me gustaría pedir?","¿Qué parte de mí necesita ser escuchada hoy?"],"phrase":"Puedo reconocer mis apoyos y dar voz a mis necesidades.","editorialStatus":"propuesta_editorial","suggestedIntents":["pedir_apoyo","adaptacion","expresion"]},{"id":"em-sfc","title":"Encefalomielitis miálgica / síndrome de fatiga crónica","category":"Fatiga persistente","aliases":["EM/SFC","ME/CFS","sindrome de fatiga cronica","encefalomielitis mialgica"],"definition":"Enfermedad prolongada con fatiga incapacitante, sueño no reparador y empeoramiento tras el esfuerzo. Puede afectar el pensamiento, la memoria y la tolerancia a permanecer erguido.","source":{"title":"Encefalomielitis miálgica/Síndrome de fatiga crónica","url":"https://medlineplus.gov/spanish/myalgicencephalomyelitischronicfatiguesyndrome.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer el valor de tu presencia","reflection":"Puedes explorar qué forma de contacto y compañía se ajusta a tus posibilidades de hoy. La imagen de la Llama puede recibirse de una manera breve y sencilla, a tu elección. Tu presencia conserva valor también cuando las actividades cambian y necesitas que otros comprendan tus límites.","questions":["¿Qué forma de compañía se ajusta a mi energía disponible?","¿Qué límite necesito comunicar para sentirme respetado?","¿Qué ayuda práctica puedo pedir sin tener que explicar todo de nuevo?"],"phrase":"Mi presencia tiene valor y mis límites merecen escucha.","suggestedIntents":["dignidad","limites","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"endometriosis","title":"Endometriosis","category":"Salud ginecológica","aliases":["endometriosis pelvica","endometriosis ovarica"],"definition":"Enfermedad en la que tejido similar al revestimiento interno del útero crece fuera de él. Puede causar dolor pélvico, menstruaciones dolorosas y problemas de fertilidad.","source":{"title":"Endometriosis","url":"https://medlineplus.gov/spanish/endometriosis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar valor a tu voz","reflection":"Tu experiencia merece palabras que la representen con precisión y respeto. Puedes acercarte a la Llama como un espacio de escucha interior, donde reconocer lo que deseas compartir y a quién quieres invitar a acompañarte.","questions":["¿Qué parte de mi experiencia quisiera que fuera mejor comprendida?","¿Qué necesito expresar sobre mis actividades, mis vínculos o mi intimidad?","¿Qué pregunta quiero preparar para mi próxima consulta?"],"phrase":"Mi experiencia merece escucha y puedo darle una voz propia.","editorialStatus":"propuesta_editorial","suggestedIntents":["expresion","dignidad","claridad"]},{"id":"enfermedad-arterial-periferica","title":"Enfermedad arterial periférica","category":"Salud cardiovascular","aliases":["EAP","enfermedad vascular periferica","arteriopatia periferica"],"definition":"Estrechamiento de arterias fuera del corazón, generalmente por acumulación de placa. Puede reducir la circulación hacia las extremidades, especialmente las piernas, y ocasionar molestias al caminar.","source":{"title":"Enfermedad arterial periférica","url":"https://medlineplus.gov/spanish/peripheralarterialdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer tu manera de avanzar","reflection":"Si desplazarte exige nuevas decisiones, puedes preguntarte qué lugares, encuentros y actividades deseas seguir habitando. La Llama puede ser una imagen de presencia en ese proceso. Recibe tus preferencias y explora qué apoyos concretos facilitarían participar en lo que amas.","questions":["¿Qué encuentro o actividad me gustaría preservar?","¿Qué dificultad necesito explicar con claridad?","¿Qué apoyo práctico podría facilitar mi día?"],"phrase":"Puedo expresar mis preferencias y construir apoyos para participar.","suggestedIntents":["adaptacion","dignidad","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"enfermedad-celiaca","title":"Enfermedad celíaca","category":"Salud digestiva","aliases":["celiaquia","celíaca","esprue celiaco"],"definition":"Enfermedad inmunitaria crónica en la que el consumo de gluten daña el intestino delgado y puede dificultar la absorción de nutrientes necesarios para el organismo.","source":{"title":"Enfermedad celíaca","url":"https://medlineplus.gov/spanish/celiacdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Participar sin dejar de escucharte","reflection":"Compartir una mesa puede reunir afecto, costumbres y necesidades concretas. Puedes contemplar la Llama como una presencia que acompaña tu participación: reconocer lo que deseas comunicar y el modo en que quieres recibir hospitalidad, conservando espacio para tus propias decisiones.","questions":["¿Cómo quisiera explicar mis necesidades cuando comparto una comida?","¿Qué forma de apoyo me hace sentir incluido?","¿Qué puedo pedir con claridad sin justificar toda mi historia?"],"phrase":"Puedo participar con alegría y dar un lugar claro a mis necesidades.","suggestedIntents":["expresion","limites","reciprocidad"],"editorialStatus":"propuesta_editorial"},{"id":"enfermedad-coronaria","title":"Enfermedad coronaria","category":"Salud cardiovascular","aliases":["cardiopatia coronaria","enfermedad de las arterias coronarias","EAC","arterioesclerosis coronaria"],"definition":"Afección de las arterias que abastecen al músculo cardíaco. La acumulación de placa puede estrecharlas y reducir el suministro de sangre y oxígeno que el corazón necesita.","source":{"title":"Enfermedad de las arterias coronarias","url":"https://medlineplus.gov/spanish/coronaryarterydisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar lugar a lo que te importa","reflection":"Conocer una condición del corazón puede invitarte a revisar cómo deseas vivir tu tiempo y tus relaciones. Si esa pregunta aparece, contempla la Llama como una compañía para reconocer tus prioridades y conversar sobre los apoyos que te gustaría tener.","questions":["¿Qué deseo conservar en mi vida cotidiana?","¿Qué preocupación quisiera compartir con alguien que me escuche?","¿Qué pregunta necesito aclarar para participar en mi cuidado?"],"phrase":"Puedo reconocer lo que me importa y darle un lugar en mi cuidado.","suggestedIntents":["eleccion_consciente","pedir_apoyo","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"addison","title":"Enfermedad de Addison","category":"Salud hormonal","aliases":["insuficiencia suprarrenal primaria","insuficiencia adrenal primaria","Addison"],"definition":"Insuficiencia de las glándulas suprarrenales para producir determinadas hormonas, especialmente cortisol y a veces aldosterona. Puede influir en la energía, la presión arterial y el equilibrio de sales.","source":{"title":"Enfermedad de Addison","url":"https://medlineplus.gov/spanish/addisondisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Construir apoyos que puedas reconocer","reflection":"Convivir con cuidados continuos puede invitarte a pensar quién conoce tus necesidades y cómo deseas comunicarlas. La Llama acompaña una presencia que participa en su propia vida. Puedes explorar qué información quieres compartir y qué acuerdos harían tu entorno más atento a ti.","questions":["¿Quién conoce lo que necesito en mi cuidado cotidiano?","¿Qué acuerdo quisiera establecer con alguien cercano?","¿Qué pregunta me ayudaría a organizarme con más claridad?"],"phrase":"Puedo construir acuerdos y reconocer apoyos para mi vida cotidiana.","suggestedIntents":["pedir_apoyo","constancia_cuidada","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"alzheimer","title":"Enfermedad de Alzheimer","category":"Neurología","aliases":["Alzheimer","demencia por Alzheimer"],"definition":"Enfermedad cerebral progresiva que afecta la memoria, el pensamiento y el lenguaje, y puede dificultar las actividades cotidianas. Es una causa frecuente de demencia.","reflectionHeading":"Encontrarse en el presente","reflection":"Para quien vive con Alzheimer y para quien acompaña, un encuentro amable puede tener valor sin exigir recuerdos o respuestas correctas. En esta propuesta, la Llama representa la dignidad de la persona. La cercanía se ofrece según sus preferencias, y el cuidador también merece apoyo.","questions":["¿Qué formas sencillas de compañía resultan agradables hoy?","¿Cómo podemos respetar las preferencias de la persona en este momento?","¿Quién puede acompañar también a quienes están cuidando?"],"phrase":"Podemos encontrarnos con respeto en este momento.","suggestedIntents":["compasion","apoyo","tristeza"],"source":{"title":"Enfermedad de Alzheimer","url":"https://medlineplus.gov/spanish/alzheimersdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"enfermedad-crohn","title":"Enfermedad de Crohn","category":"Salud digestiva","aliases":["Crohn","enteritis regional"],"definition":"Enfermedad inflamatoria crónica que puede afectar cualquier parte del tracto digestivo. Con frecuencia compromete el intestino delgado y puede causar dolor abdominal, diarrea y cansancio.","source":{"title":"Enfermedad de Crohn","url":"https://medlineplus.gov/spanish/crohnsdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Acompañarte en los días cambiantes","reflection":"Si tus posibilidades varían, puedes explorar cómo organizar tus vínculos y proyectos sin exigir a cada día la misma respuesta. La Llama puede ser una imagen de continuidad interior, desde la que reconoces lo disponible y conversas sobre el apoyo que deseas.","questions":["¿Qué me ayuda cuando tengo que cambiar un plan?","¿A quién quisiera explicar cómo estoy viviendo estos cambios?","¿Qué parte de mi vida quiero seguir cultivando a mi ritmo?"],"phrase":"Puedo reconocer el día que tengo y encontrar una forma propia de participar.","suggestedIntents":["adaptacion","compasion","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"graves","title":"Enfermedad de Graves","category":"Salud hormonal","aliases":["Graves Basedow","enfermedad de Basedow","bocio toxico difuso"],"definition":"Enfermedad autoinmune que estimula la glándula tiroides y provoca producción excesiva de hormonas. Puede acompañarse de alteraciones en los ojos y, con menor frecuencia, en la piel.","source":{"title":"Enfermedad de Graves","url":"https://medlineplus.gov/spanish/ency/article/000358.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Mirarte con amplitud durante los cambios","reflection":"Si notas cambios que afectan cómo te sientes o cómo te ven, puedes explorar qué significa atravesarlos para ti. La imagen de la Llama invita a reconocer tu dignidad. Escucha qué quieres compartir, qué prefieres reservar y qué compañía te resulta respetuosa.","questions":["¿Qué cambio me está afectando más personalmente?","¿Qué tipo de comentario o compañía me hace sentir respetado?","¿Qué quiero comunicar sobre mi experiencia?"],"phrase":"Puedo mirar mi experiencia con amplitud y elegir cómo compartirla.","suggestedIntents":["dignidad","expresion","limites"],"editorialStatus":"propuesta_editorial"},{"id":"enfermedad-meniere","title":"Enfermedad de Ménière","category":"Oído y equilibrio","aliases":["Meniere","sindrome de Meniere"],"definition":"Trastorno del oído interno que puede provocar episodios de vértigo, cambios de audición, tinnitus y sensación de presión en el oído. Su evolución varía entre personas.","source":{"title":"Enfermedad de Ménière","url":"https://medlineplus.gov/spanish/menieresdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Conservar referencias de compañía","reflection":"Cuando los cambios de audición o equilibrio afectan tus planes, puedes explorar qué acuerdos te harían sentir acompañado. La Llama puede ser una imagen de presencia tranquila durante un momento cómodo. Quizás quieras expresar una necesidad, ajustar un encuentro o compartir lo que te preocupa.","questions":["¿Qué necesito que comprendan cuando mis planes cambian?","¿Qué acuerdo práctico me daría más apoyo?","¿Qué deseo seguir compartiendo con las personas cercanas?"],"phrase":"Puedo pedir acuerdos que acompañen mi vida cotidiana.","suggestedIntents":["adaptacion","apoyo","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"parkinson","title":"Enfermedad de Parkinson","category":"Neurología","aliases":["Parkinson","mal de Parkinson"],"definition":"Trastorno neurológico progresivo asociado con una disminución de dopamina en el cerebro. Puede producir lentitud de movimientos, rigidez, temblor y dificultades de equilibrio, entre otros síntomas.","reflectionHeading":"Un ritmo propio, una dignidad intacta","reflection":"Cuando algunas acciones requieren más tiempo, puedes explorar cómo deseas que te acompañen. La imagen de la Llama permite contemplar una dignidad que no depende de la velocidad del cuerpo. También hay lugar para la tristeza por los cambios, sin exigir optimismo ni una lección espiritual.","questions":["¿En qué situaciones necesitas que respeten más tu tiempo?","¿Qué actividad o vínculo sigue siendo importante para ti?","¿Cómo quisieras pedir ayuda sin perder participación en las decisiones?"],"phrase":"Mi ritmo puede cambiar; mi derecho al respeto permanece.","suggestedIntents":["dignidad","adaptacion","pedir_apoyo"],"source":{"title":"Enfermedad de Parkinson","url":"https://medlineplus.gov/spanish/parkinsonsdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"enfermedad-hepatica-esteatosica","title":"Enfermedad hepática esteatósica","category":"Salud hepática","aliases":["higado graso","esteatosis hepatica","MASLD","MASH"],"definition":"Acumulación excesiva de grasa en el hígado. Comprende distintas formas, algunas relacionadas con alteraciones metabólicas, y en ciertos casos puede acompañarse de inflamación y daño hepático.","source":{"title":"Esteatosis hepática","url":"https://medlineplus.gov/spanish/steatoticliverdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Construir una relación respetuosa con tu cuidado","reflection":"Puedes preguntarte cómo te relacionas con la información que recibes sobre tu salud y qué apoyo facilitaría tu cuidado cotidiano. En la contemplación, la Llama invita a una mirada digna y paciente, capaz de escuchar preguntas y reconocer pasos posibles.","questions":["¿Cómo me siento con la información que he recibido?","¿Qué necesito aclarar para participar en mi cuidado?","¿Qué clase de compañía me ayuda a dar continuidad a mis decisiones?"],"phrase":"Puedo participar en mi cuidado desde la dignidad y la comprensión.","suggestedIntents":["dignidad","constancia_cuidada","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"epoc","title":"Enfermedad pulmonar obstructiva crónica","category":"Salud respiratoria","aliases":["EPOC","EOPC","enfermedad de obstruccion pulmonar cronica"],"definition":"Conjunto de enfermedades que limitan el flujo de aire en los pulmones y dificultan la respiración. Puede incluir enfisema, bronquitis crónica, tos y cansancio al realizar actividades.","source":{"title":"Enfermedad de obstrucción pulmonar crónica","url":"https://medlineplus.gov/spanish/copd.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Participar desde tus posibilidades","reflection":"Si algunas actividades requieren ahora otro ritmo, puedes preguntarte qué quieres conservar en tu vida y qué apoyo facilitaría tu participación. La Llama puede acompañar esa escucha como una imagen de presencia, abierta a tus capacidades y a tus deseos actuales.","questions":["¿Qué encuentro o actividad sigue siendo importante para mí?","¿Qué ayuda concreta facilitaría mi participación?","¿Cómo deseo expresar mi ritmo a las personas cercanas?"],"phrase":"Puedo participar con un ritmo propio y recibir apoyo.","suggestedIntents":["adaptacion","expresion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"enfermedad-renal-cronica","title":"Enfermedad renal crónica","category":"Salud renal y urinaria","aliases":["ERC","insuficiencia renal cronica","enfermedad cronica del rinon"],"definition":"Daño persistente de los riñones que reduce su capacidad para filtrar la sangre y mantener el equilibrio del organismo. Puede avanzar lentamente y afectar otras funciones corporales.","source":{"title":"Enfermedad renal crónica","url":"https://medlineplus.gov/spanish/chronickidneydisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Sostener tu presencia en el tiempo","reflection":"Un proceso prolongado puede invitarte a conversar sobre tu tiempo, tus roles y las ayudas que deseas recibir. La Llama puede simbolizar la continuidad de tu presencia: sigues teniendo preferencias, vínculos y preguntas que merecen espacio dentro de tu cuidado.","questions":["¿Qué parte de mi vida quiero cuidar además de mis rutinas de salud?","¿Qué responsabilidades necesito compartir?","¿Qué deseo expresar a las personas que participan en mi cuidado?"],"phrase":"Puedo recibir apoyo y conservar una voz propia en mi camino.","suggestedIntents":["constancia_cuidada","reciprocidad","limites"],"editorialStatus":"propuesta_editorial"},{"id":"epilepsia","title":"Epilepsia","category":"Neurología","aliases":["crisis epilepticas","trastorno epileptico"],"definition":"Enfermedad cerebral caracterizada por crisis recurrentes relacionadas con actividad eléctrica anormal de las neuronas. Las crisis pueden afectar movimientos, sensaciones, comportamiento o nivel de conciencia.","reflectionHeading":"Conservar tu voz ante la incertidumbre","reflection":"La posibilidad de una crisis puede despertar preguntas sobre autonomía y confianza. Puedes explorar esas preguntas sin reducir tu identidad al diagnóstico. La Llama, como imagen de tu dignidad, invita a reconocer también tus preferencias, vínculos y proyectos, dejando que el apoyo respete tu voz.","questions":["¿Qué aspecto de tu vida quieres que los demás sigan reconociendo más allá del diagnóstico?","¿Qué apoyo te resulta respetuoso y cuál se siente invasivo?","¿Qué te gustaría expresar acerca de la incertidumbre que estás viviendo?"],"phrase":"Mi experiencia merece ser escuchada y mi voz sigue contando.","suggestedIntents":["incertidumbre","expresion","limites"],"source":{"title":"Epilepsia","url":"https://medlineplus.gov/spanish/epilepsy.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"esclerodermia","title":"Esclerodermia","category":"Enfermedades autoinmunes","aliases":["esclerosis sistemica","esclerodermia localizada"],"definition":"Enfermedad autoinmune que causa inflamación y engrosamiento de la piel. Algunas formas afectan también vasos sanguíneos y órganos internos, con manifestaciones diferentes según la persona.","source":{"title":"Esclerodermia","url":"https://medlineplus.gov/spanish/scleroderma.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Conservar tu lugar en las decisiones","reflection":"Cuando aparecen cambios en tu cuerpo o en tus actividades, puedes explorar qué decisiones quieres comprender y compartir. La Llama invita a reconocer tu propia voz, las preguntas que deseas formular y la ayuda que puede acompañarte en cada paso de tu vida.","questions":["¿Qué cambio está pidiendo más atención de mi parte?","¿Qué información necesito comprender antes de una decisión?","¿Cómo quiero participar en las conversaciones sobre mi cuidado?"],"phrase":"Puedo preguntar, comprender y participar con mi propia voz.","suggestedIntents":["eleccion_consciente","expresion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"esclerosis-multiple","title":"Esclerosis múltiple","category":"Neurología","aliases":["EM","esclerosis multiple recurrente remitente"],"definition":"Enfermedad del sistema nervioso central que daña la mielina protectora de las fibras nerviosas. Puede alterar la comunicación entre cerebro y cuerpo de distintas maneras.","reflectionHeading":"Hacer espacio a los días diferentes","reflection":"Si tus posibilidades cambian de un día a otro, quizá necesites revisar expectativas sin sentir que incumples contigo. Puedes contemplar la Llama como una presencia que acompaña esa variación. Dar nombre a lo que necesitas hoy permite conversar sobre apoyo, límites y decisiones que conservan sentido para ti.","questions":["¿Qué necesitas que otros comprendan sobre tus días diferentes?","¿Qué expectativa deseas revisar con más amabilidad?","¿Qué elección sigue estando en tus manos hoy?"],"phrase":"Puedo escuchar mis necesidades de hoy sin compararlas con las de ayer.","suggestedIntents":["adaptacion","limites","pedir_apoyo"],"source":{"title":"Esclerosis múltiple","url":"https://medlineplus.gov/spanish/multiplesclerosis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"espondilitis-anquilosante","title":"Espondilitis anquilosante","category":"Movimiento y articulaciones","aliases":["espondilitis reumatoide","espondiloartritis axial radiografica"],"definition":"Tipo de artritis que inflama articulaciones de la columna vertebral y su unión con la pelvis. Puede causar dolor, rigidez y limitación del movimiento.","source":{"title":"Espondilitis anquilosante","url":"https://medlineplus.gov/spanish/ankylosingspondylitis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Elegir tu manera de participar","reflection":"Puedes preguntarte qué actividades tienen sentido para ti y qué condiciones facilitan tu participación. La Llama acompaña una escucha de tus posibilidades actuales, tus preferencias y tus relaciones, para que cada elección tenga espacio para incluir lo que necesitas y lo que valoras.","questions":["¿Qué actividad conecta con algo importante para mí?","¿Qué condiciones me ayudarían a participar con más comodidad?","¿Qué necesito conversar sobre mi disponibilidad?"],"phrase":"Puedo elegir cómo participar y expresar lo que valoro.","suggestedIntents":["adaptacion","eleccion_consciente","limites"],"editorialStatus":"propuesta_editorial"},{"id":"estrenimiento","title":"Estreñimiento","category":"Salud digestiva","aliases":["constipacion","dificultad para evacuar","heces duras"],"definition":"Evacuaciones poco frecuentes o difíciles, a menudo con heces duras y secas. Puede presentarse de forma ocasional o persistente y tener distintas causas.","source":{"title":"Estreñimiento","url":"https://medlineplus.gov/spanish/constipation.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Acompañarte con paciencia","reflection":"Puedes observar cómo te hablas cuando aparece una incomodidad corporal. La contemplación de la Llama ofrece un espacio para la paciencia: reconocer tu experiencia y darle palabras que te permitan cuidarte con respeto.","questions":["¿Qué sentimientos acompañan esta incomodidad?","¿Qué me ayudaría a vivir este momento con más intimidad y respeto?","¿Qué pregunta quiero expresar para comprender mejor lo que me ocurre?"],"phrase":"Puedo tratarme con paciencia y expresar mis preguntas.","editorialStatus":"propuesta_editorial","suggestedIntents":["compasion","autoacogida","claridad"]},{"id":"fibrilacion-auricular","title":"Fibrilación auricular","category":"Salud cardiovascular","aliases":["FA","fibrilacion atrial","fibriloaleteo auricular"],"definition":"Alteración del ritmo cardíaco que produce latidos irregulares y a veces rápidos. Las cavidades superiores e inferiores del corazón pierden parte de su coordinación habitual.","source":{"title":"Fibrilación auricular","url":"https://medlineplus.gov/spanish/atrialfibrillation.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar palabras a la incertidumbre","reflection":"Cuando una experiencia corporal despierta incertidumbre, puedes distinguir lo que observas de las historias que imaginas. La Llama puede acompañar una pausa de comprensión: escuchar tus preguntas, reconocer tus apoyos y elegir a quién deseas pedir información o compañía.","questions":["¿Qué sé de mi experiencia y qué necesito preguntar?","¿Qué pensamiento está ocupando más espacio en mí?","¿Qué conversación me ayudaría a sentirme acompañado?"],"phrase":"Puedo escuchar mis preguntas y buscar claridad con compañía.","suggestedIntents":["incertidumbre","claridad","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"fibromialgia","title":"Fibromialgia","category":"Dolor persistente","aliases":["fibromialgia cronica","fibroniebla"],"definition":"Afección crónica caracterizada por dolor extendido por el cuerpo y fatiga. Puede acompañarse de problemas de sueño y dificultades para concentrarse o recordar.","source":{"title":"Fibromialgia","url":"https://medlineplus.gov/spanish/fibromyalgia.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer la experiencia que otros no ven","reflection":"Puedes dar palabras a lo que estás viviendo, aun cuando resulte difícil explicarlo. La Llama ofrece una imagen de reconocimiento interior: recibir tu experiencia, identificar qué necesitas y elegir con quién compartirla.","questions":["¿Qué me está costando explicar?","¿Qué ayuda concreta se acercaría a mi necesidad de hoy?","¿Cómo quiero acompañarme cuando mi energía cambia?"],"phrase":"Puedo reconocer mi experiencia y pedir compañía a mi medida.","editorialStatus":"propuesta_editorial","suggestedIntents":["expresion","dignidad","pedir_apoyo"]},{"id":"fibrosis-pulmonar","title":"Fibrosis pulmonar","category":"Salud respiratoria","aliases":["cicatrizacion pulmonar","fibrosis pulmonar idiopatica"],"definition":"Cicatrización del tejido profundo de los pulmones que lo vuelve más grueso y rígido. Puede dificultar la respiración y el paso de oxígeno a la sangre.","source":{"title":"Fibrosis pulmonar","url":"https://medlineplus.gov/spanish/pulmonaryfibrosis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Encontrar compañía ante lo incierto","reflection":"Puedes explorar qué preguntas surgen cuando imaginas tu día o miras hacia adelante. En un momento tranquilo, la Llama puede representar compañía para reconocer lo que sientes, preparar una conversación y elegir qué información o cercanía deseas recibir hoy.","questions":["¿Qué pregunta está ocupando mi atención?","¿Qué quiero conversar con quienes participan en mi cuidado?","¿Qué forma de compañía me resulta valiosa hoy?"],"phrase":"Puedo compartir mis preguntas y recibir compañía en este momento.","suggestedIntents":["incertidumbre","pedir_apoyo","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"gastritis","title":"Gastritis","category":"Salud digestiva","aliases":["gastritis aguda","gastritis cronica","inflamacion del estomago"],"definition":"Inflamación del revestimiento del estómago que puede durar poco tiempo o persistir durante meses o años. Algunas personas presentan molestias y otras no tienen síntomas.","source":{"title":"Gastritis","url":"https://medlineplus.gov/spanish/ency/article/001150.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Poner en palabras tus preguntas","reflection":"Cuando aparece una molestia, puedes necesitar palabras para describirla y preguntas para comprender lo que estás viviendo. La Llama puede acompañar esa escucha sencilla: observar tu experiencia, reconocer tus inquietudes y darles un lugar en una conversación de cuidado.","questions":["¿Qué me gustaría comprender mejor sobre mi experiencia?","¿Qué pregunta estoy posponiendo expresar?","¿Cómo puedo hablarme con amabilidad mientras busco respuestas?"],"phrase":"Puedo escuchar mis preguntas y expresarlas con claridad.","suggestedIntents":["claridad","expresion","compasion"],"editorialStatus":"propuesta_editorial"},{"id":"glaucoma","title":"Glaucoma","category":"Visión","aliases":["glaucoma de angulo abierto","glaucoma de angulo cerrado"],"definition":"Grupo de enfermedades que dañan el nervio óptico y pueden reducir la visión. Algunas formas avanzan sin síntomas perceptibles al principio y se detectan mediante evaluaciones oculares.","reflectionHeading":"Acompañar la incertidumbre con claridad","reflection":"Un diagnóstico puede traer preguntas incluso cuando no notas cambios en la visión. Puedes dar espacio a la inquietud y preparar lo que necesitas comprender. La Llama, como símbolo contemplativo, acompaña tu relación con esa incertidumbre; no permite medir la enfermedad ni anticipar cómo evolucionará.","questions":["¿Qué pregunta te gustaría llevar a tu próxima conversación con el equipo de salud?","¿Quién puede ayudarte a ordenar la información que recibes?","¿Qué necesitas hoy para sentirte acompañado o acompañada sin minimizar tu preocupación?"],"phrase":"Puedo buscar información clara y recibir apoyo paso a paso.","suggestedIntents":["incertidumbre","claridad","pedir_apoyo"],"source":{"title":"Glaucoma","url":"https://medlineplus.gov/spanish/glaucoma.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"gota","title":"Gota","category":"Movimiento y articulaciones","aliases":["artritis gotosa","crisis de gota"],"definition":"Forma de artritis inflamatoria relacionada con depósitos de cristales de urato en las articulaciones. Puede provocar episodios de dolor intenso, hinchazón y enrojecimiento, a menudo en el pie.","source":{"title":"Gota","url":"https://medlineplus.gov/spanish/gout.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Acompañar lo que interrumpe tu día","reflection":"Un episodio doloroso puede modificar planes y despertar frustración. Si te ocurre, puedes reconocer lo que sientes sin apresurarte a corregirlo. La Llama ofrece una imagen de compañía para expresar necesidades, revisar compromisos y recibir ayuda mientras atraviesas ese cambio en tu jornada.","questions":["¿Qué siento al tener que cambiar mis planes?","¿Qué compromiso necesito renegociar?","¿Qué ayuda concreta haría mi día más llevadero?"],"phrase":"Puedo reconocer mi frustración y comunicar lo que necesito hoy.","suggestedIntents":["expresion","apoyo","compasion"],"editorialStatus":"propuesta_editorial"},{"id":"gripe","title":"Gripe","category":"Infecciones","aliases":["influenza","gripa","trancazo"],"definition":"Infección respiratoria causada por los virus de la influenza. Puede producir fiebre, tos, dolores musculares y cansancio, con una intensidad que varía de una persona a otra.","source":{"title":"Gripe","url":"https://medlineplus.gov/spanish/flu.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Hacer espacio en el día","reflection":"Un cambio repentino en tus posibilidades puede mostrar cuánto dependía tu jornada de estar disponible. Puedes contemplar la Llama como una invitación a reconocer tus necesidades actuales, reorganizar compromisos y recibir con sencillez la ayuda que otros puedan ofrecer.","questions":["¿Qué compromiso necesito reorganizar hoy?","¿Qué tarea puedo compartir o dejar para otro momento?","¿Cómo quiero hablarme mientras mis posibilidades son distintas?"],"phrase":"Puedo reorganizar mi día con claridad y amabilidad.","suggestedIntents":["descanso","compasion","limites"],"editorialStatus":"propuesta_editorial"},{"id":"hemorroides","title":"Hemorroides","category":"Salud digestiva","aliases":["almorranas","hemorroides internas","hemorroides externas"],"definition":"Venas hinchadas en la región anal o en la parte inferior del recto. Pueden ser internas o externas y causar picazón, molestias o sangrado.","source":{"title":"Hemorroides","url":"https://medlineplus.gov/spanish/hemorrhoids.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar dignidad a lo que cuesta nombrar","reflection":"Hay molestias que resulta incómodo conversar. Puedes contemplar la Llama como una presencia de respeto mientras encuentras palabras sencillas para describir tu experiencia. Tu intimidad puede acompañarse de la libertad de hacer preguntas y recibir la atención que buscas.","questions":["¿Qué me cuesta nombrar de esta experiencia?","¿Qué necesito para sentirme cómodo al pedir orientación?","¿Qué palabras sencillas me ayudarían a explicar mi necesidad?"],"phrase":"Puedo hablar de mi cuerpo con respeto y cuidar mi intimidad.","suggestedIntents":["dignidad","expresion","compasion"],"editorialStatus":"propuesta_editorial"},{"id":"hepatitis-b","title":"Hepatitis B","category":"Salud hepática","aliases":["VHB","hepatitis B cronica","hepatitis B aguda"],"definition":"Infección del hígado causada por el virus de la hepatitis B. Puede ser breve o persistente y afectar de distintas maneras el funcionamiento hepático.","source":{"title":"Hepatitis B","url":"https://medlineplus.gov/spanish/hepatitisb.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Elegir cómo quieres ser acompañado","reflection":"Puedes explorar con quién deseas hablar de tu experiencia y qué necesitas de esa conversación. La Llama puede simbolizar un espacio interior de dignidad, desde el que reconoces tus preguntas, eliges tus palabras y buscas relaciones donde puedas sentirte respetado.","questions":["¿Qué quiero compartir sobre lo que estoy viviendo?","¿Qué respuesta me haría sentir acompañado y respetado?","¿Qué información necesito para conversar con más claridad?"],"phrase":"Mi experiencia merece respeto y puedo elegir cómo compartirla.","suggestedIntents":["limites","confianza_discernida","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"hepatitis-c","title":"Hepatitis C","category":"Salud hepática","aliases":["VHC","hepatitis C cronica","hepatitis C aguda"],"definition":"Infección causada por el virus de la hepatitis C que inflama el hígado. Puede ser de corta duración o persistir y ocasionar daño hepático con el tiempo.","source":{"title":"Hepatitis C","url":"https://medlineplus.gov/spanish/hepatitisc.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Encontrar palabras sin juzgarte","reflection":"Las preguntas sobre una condición de salud pueden convivir con emociones muy distintas. Puedes acercarte a la Llama como una imagen de acogida mientras nombras lo que sientes, reconoces tus necesidades y decides qué compañía te resultaría valiosa en este proceso.","questions":["¿Qué emoción quiero poder nombrar con libertad?","¿Con quién me siento escuchado sin tener que defenderme?","¿Qué pregunta deseo llevar a mi próxima conversación de cuidado?"],"phrase":"Puedo expresar mi experiencia y recibir una escucha respetuosa.","suggestedIntents":["dignidad","autoacogida","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"hiperplasia-prostatica-benigna","title":"Hiperplasia prostática benigna","category":"Salud renal y urinaria","aliases":["HPB","prostata agrandada","hipertrofia prostatica benigna"],"definition":"Agrandamiento no canceroso de la próstata que puede comprimir la uretra y dificultar la salida de la orina. Es frecuente con el avance de la edad.","source":{"title":"Agrandamiento de la próstata","url":"https://medlineplus.gov/spanish/enlargedprostatebph.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Conversar sobre los cambios con libertad","reflection":"Los cambios corporales pueden despertar preguntas sobre la vida cotidiana, la intimidad o la etapa que atraviesas. Puedes contemplar la Llama como una presencia que acompaña tu voz, dando espacio a lo que quieras comprender y a las conversaciones que elijas tener.","questions":["¿Qué preguntas tengo sobre los cambios que estoy viviendo?","¿Qué tema quisiera conversar con más libertad?","¿Qué me haría sentir cómodo al expresar una preocupación íntima?"],"phrase":"Puedo conversar sobre mis cambios con claridad y respeto.","suggestedIntents":["claridad","expresion","confianza_discernida"],"editorialStatus":"propuesta_editorial"},{"id":"hipertension","title":"Hipertensión","category":"Salud cardiovascular","aliases":["presion arterial alta","tension alta","alta presion"],"definition":"Elevación mantenida de la presión que ejerce la sangre sobre las arterias. A menudo pasa inadvertida porque no produce síntomas; se identifica mediante mediciones y evaluación profesional.","source":{"title":"Presión arterial alta","url":"https://medlineplus.gov/spanish/highbloodpressure.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Habitar el cuidado cotidiano","reflection":"Convivir con una condición que requiere seguimiento puede despertar preguntas sobre el cuidado y la continuidad. La Llama puede acompañarte como una imagen de presencia: atender lo cotidiano, reconocer tus recursos y pedir el apoyo que elijas.","questions":["¿Cómo estoy viviendo el cuidado de mi salud?","¿Qué me ayuda a sostener mis compromisos cotidianos?","¿Qué pregunta quiero llevar a mi próxima conversación con el equipo que me atiende?"],"phrase":"Puedo dar continuidad a mi cuidado con presencia y apoyo.","editorialStatus":"propuesta_editorial","suggestedIntents":["constancia_cuidada","pedir_apoyo","claridad"]},{"id":"hipertiroidismo","title":"Hipertiroidismo","category":"Salud hormonal","aliases":["tiroides hiperactiva","hiperfuncion tiroidea","hipertireosis"],"definition":"Producción excesiva de hormonas tiroideas respecto a las necesidades del organismo. Puede acelerar distintas funciones corporales y acompañarse de palpitaciones, pérdida de peso o intolerancia al calor.","source":{"title":"Hipertiroidismo","url":"https://medlineplus.gov/spanish/hyperthyroidism.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Distinguir y nombrar tu experiencia","reflection":"Cuando tu experiencia corporal se siente distinta, puedes dar tiempo a reconocer qué estás viviendo y cómo te afecta. La Llama acompaña una escucha sin prisa por explicarlo todo. Quizás surja una pregunta, una necesidad de descanso o una conversación que quieras preparar.","questions":["¿Qué cambio de mi experiencia me cuesta describir?","¿Qué quisiera que otras personas comprendieran?","¿Qué momento de mi día necesita una organización más amable?"],"phrase":"Puedo describir lo que vivo y encontrar palabras para mis necesidades.","suggestedIntents":["expresion","descanso","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"hipotiroidismo","title":"Hipotiroidismo","category":"Salud hormonal","aliases":["tiroides hipoactiva","hipofuncion tiroidea","insuficiencia tiroidea"],"definition":"Ocurre cuando la tiroides produce menos hormonas de las que el cuerpo necesita. Esto puede enlentecer diversas funciones del organismo y afectar la energía disponible.","source":{"title":"Hipotiroidismo","url":"https://medlineplus.gov/spanish/hypothyroidism.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Escuchar tus posibilidades de hoy","reflection":"Puedes preguntarte qué ritmo estás pudiendo sostener y qué expectativas merecen una conversación. La Llama acompaña una presencia atenta a lo concreto: tus recursos, tu tiempo y la ayuda que deseas recibir.","questions":["¿Qué estoy pudiendo hacer hoy?","¿Qué expectativa quisiera revisar con amabilidad?","¿Qué ayuda facilitaría una tarea que me importa?"],"phrase":"Puedo reconocer mis posibilidades y elegir un paso a mi medida.","editorialStatus":"propuesta_editorial","suggestedIntents":["adaptacion","pedir_apoyo","compasion"]},{"id":"incontinencia-urinaria","title":"Incontinencia urinaria","category":"Salud renal y urinaria","aliases":["perdida de orina","escapes de orina","perdida de control de la vejiga"],"definition":"Pérdida involuntaria de orina por dificultades para controlar la vejiga. Existen varios tipos, con características y causas diferentes, y puede afectar las actividades diarias.","source":{"title":"Incontinencia urinaria","url":"https://medlineplus.gov/spanish/urinaryincontinence.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Participar desde el respeto a ti","reflection":"Puedes explorar cómo mantener espacio para las actividades y relaciones que te importan. La Llama puede acompañar una mirada digna sobre tu experiencia, desde la que reconoces tus preferencias, cuidas tu intimidad y eliges cómo conversar sobre el apoyo que necesitas.","questions":["¿Qué actividad me gustaría vivir con mayor tranquilidad?","¿Qué necesito para sentirme respetado al hablar de esto?","¿Qué ayuda o adaptación quisiera poder conversar?"],"phrase":"Puedo cuidar mi intimidad y seguir dando lugar a lo que amo.","suggestedIntents":["dignidad","limites","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"infeccion-urinaria","title":"Infección urinaria","category":"Salud renal y urinaria","aliases":["infeccion de vias urinarias","ITU","infeccion del tracto urinario"],"definition":"Infección que afecta alguna parte del aparato urinario, como la vejiga, la uretra o los riñones. Puede producir molestias al orinar y cambios en la frecuencia urinaria.","source":{"title":"Infecciones de las vías urinarias","url":"https://medlineplus.gov/spanish/urinarytractinfections.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer una necesidad concreta","reflection":"Puedes hacer espacio para describir lo que vives y reconocer cómo afecta a tu jornada. La contemplación de la Llama invita a una atención amable, donde tus necesidades cotidianas encuentran palabras y puedes elegir a quién pedir información o ayuda.","questions":["¿Qué necesito explicar con precisión?","¿Qué parte de mi día requiere una adaptación temporal?","¿Cómo puedo pedir ayuda de una manera que me resulte cómoda?"],"phrase":"Puedo atender mi experiencia y expresar una necesidad concreta.","suggestedIntents":["expresion","claridad","compasion"],"editorialStatus":"propuesta_editorial"},{"id":"infertilidad","title":"Infertilidad","category":"Salud reproductiva","aliases":["problemas para concebir","esterilidad"],"definition":"Dificultad para lograr un embarazo después de un período de relaciones sexuales regulares sin anticoncepción. Puede involucrar factores de cualquiera de los integrantes de la pareja.","source":{"title":"Infertilidad","url":"https://medlineplus.gov/spanish/infertility.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar lugar a tus deseos y a tus límites","reflection":"Puedes explorar cómo conviven tus deseos, tus expectativas y las preguntas de otras personas. La Llama puede representar un espacio íntimo donde reconocer tu experiencia con respeto. Tú decides qué conversaciones abrir, qué límites expresar y qué compañía deseas para transitar la incertidumbre.","questions":["¿Qué deseo quiero escuchar con mis propias palabras?","¿Qué preguntas de otras personas prefiero dejar sin responder?","¿Qué compañía reconoce mi experiencia sin apresurarla?"],"phrase":"Mis deseos, mis emociones y mis límites merecen respeto.","suggestedIntents":["autoacogida","limites","tristeza"],"editorialStatus":"propuesta_editorial"},{"id":"insomnio","title":"Insomnio","category":"Sueño","aliases":["dificultad para dormir","no puedo dormir","despertares nocturnos"],"definition":"Dificultad para iniciar o mantener el sueño, o despertar antes de lo deseado. Puede dejar sensación de descanso insuficiente y afectar el funcionamiento durante el día.","source":{"title":"Insomnio","url":"https://medlineplus.gov/spanish/insomnia.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar espacio a la noche","reflection":"Cuando descansar se vuelve difícil, puedes acercarte a la noche con curiosidad y ternura. La Llama ofrece una imagen de compañía interior: un lugar donde reconocer cómo llegas al final del día y qué deseas recibir en este momento.","questions":["¿Qué estoy sintiendo mientras espero dormir?","¿Qué asunto quisiera dejar anotado para retomarlo mañana?","¿Qué forma de compañía o de recogimiento me resultaría amable esta noche?"],"phrase":"Puedo acompañarme con ternura mientras encuentro mi propio ritmo.","editorialStatus":"propuesta_editorial","suggestedIntents":["descanso","autoacogida","claridad"]},{"id":"insuficiencia-cardiaca","title":"Insuficiencia cardíaca","category":"Salud cardiovascular","aliases":["fallo cardiaco","insuficiencia cardiaca congestiva","ICC"],"definition":"Afección en la que el corazón no impulsa suficiente sangre para cubrir las necesidades del organismo. Puede relacionarse con debilidad del músculo o dificultad para llenarse adecuadamente.","source":{"title":"Fallo cardíaco","url":"https://medlineplus.gov/spanish/heartfailure.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Participar a tu propio ritmo","reflection":"Si tus actividades requieren ajustes, puedes explorar qué formas de participación siguen siendo significativas para ti. En la imagen de la Llama, tu presencia conserva dignidad. Puedes escuchar la tristeza por lo que cambia y reconocer la compañía que deseas recibir.","questions":["¿Qué actividad tiene un valor especial para mí?","¿Qué cambio de mi vida necesito conversar?","¿Qué ayuda me permitiría participar con más comodidad?"],"phrase":"Mi presencia tiene valor y puedo recibir ayuda a mi medida.","suggestedIntents":["adaptacion","pedir_apoyo","tristeza"],"editorialStatus":"propuesta_editorial"},{"id":"leucemia","title":"Leucemia","category":"Acompañamiento oncológico","aliases":["leucemia aguda","leucemia cronica","cáncer"],"definition":"Cáncer de las células sanguíneas que comienza en tejidos donde se forma la sangre, como la médula ósea. Las células anormales pueden desplazar a las células sanas.","source":{"title":"Leucemia","url":"https://medlineplus.gov/spanish/leukemia.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer la red que te acompaña","reflection":"Puedes mirar quiénes participan en tu día y qué ayuda te resulta más valiosa. La imagen de la Llama puede representar una presencia que se expresa también a través de vínculos concretos. Quizás quieras nombrar una necesidad, agradecer una compañía o reservar un momento propio.","questions":["¿Qué ayuda concreta necesito esta semana?","¿Cómo quisiera organizar las visitas o los mensajes?","¿Qué pequeño espacio personal me gustaría conservar?"],"phrase":"Puedo recibir ayuda y conservar un espacio propio.","suggestedIntents":["pedir_apoyo","reciprocidad","limites"],"editorialStatus":"propuesta_editorial"},{"id":"linfoma","title":"Linfoma","category":"Acompañamiento oncológico","aliases":["linfoma de Hodgkin","linfoma no Hodgkin","cáncer"],"definition":"Conjunto de cánceres que afectan al sistema linfático y a células inmunitarias llamadas linfocitos. Incluye el linfoma de Hodgkin y diversos linfomas no Hodgkin.","source":{"title":"Linfoma","url":"https://medlineplus.gov/spanish/lymphoma.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Hacer espacio a preguntas distintas","reflection":"Un proceso de salud puede reunir preguntas prácticas, emociones y deseos que cambian con el tiempo. Puedes acercarte a cada uno con paciencia. La Llama puede acompañar esa escucha interior, mientras distingues qué necesitas comprender, qué quieres compartir y qué compañía deseas recibir hoy.","questions":["¿Qué pregunta es más importante para mí ahora?","¿Qué emoción quisiera poder nombrar?","¿A quién puedo pedir una ayuda concreta?"],"phrase":"Puedo reconocer lo que necesito en este momento.","suggestedIntents":["incertidumbre","claridad","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"lupus","title":"Lupus","category":"Enfermedades autoinmunes","aliases":["lupus eritematoso sistemico","LES","lupus cutaneo"],"definition":"Enfermedad autoinmune crónica en la que el sistema inmunitario provoca inflamación y puede afectar tejidos sanos. Sus manifestaciones varían y pueden involucrar diversos órganos.","source":{"title":"Lupus","url":"https://medlineplus.gov/spanish/lupus.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Escuchar el día que estás viviendo","reflection":"Puedes reconocer cómo están hoy tus posibilidades y qué deseas conservar en tus vínculos y actividades. La Llama acompaña esa atención al presente como una imagen de compañía: dar palabras a tu experiencia y permitir que tus necesidades participen en las decisiones.","questions":["¿Qué está siendo posible para mí hoy?","¿Qué necesito ajustar o conversar en mis compromisos?","¿Qué persona podría acompañarme en una tarea concreta?"],"phrase":"Puedo escuchar mi presente y hacer lugar a mis necesidades.","suggestedIntents":["adaptacion","expresion","limites"],"editorialStatus":"propuesta_editorial"},{"id":"melanoma","title":"Melanoma","category":"Acompañamiento oncológico","aliases":["melanoma cutaneo","cáncer"],"definition":"Tipo de cáncer de piel que puede aparecer en un lunar existente o como una lesión nueva. Puede cambiar de tamaño, forma, color o textura.","source":{"title":"Melanoma","url":"https://medlineplus.gov/spanish/melanoma.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar espacio a lo que sientes al esperar","reflection":"Si las consultas o los resultados abren preguntas sobre el futuro, puedes reconocer cómo estás viviendo esa espera. La Llama puede simbolizar compañía en el momento presente. Tu reflexión puede centrarse en una emoción, una conversación pendiente o un vínculo que deseas tener cerca.","questions":["¿Qué siento mientras espero una respuesta?","¿Qué pregunta quiero dejar preparada?","¿Qué persona o actividad me gustaría tener presente hoy?"],"phrase":"Puedo recibir compañía mientras doy tiempo a mis preguntas.","suggestedIntents":["incertidumbre","autoacogida","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"migrana","title":"Migraña","category":"Neurología","aliases":["jaqueca","migraña"],"definition":"Trastorno con episodios recurrentes de dolor de cabeza, a menudo pulsátil y de intensidad moderada o fuerte, que puede acompañarse de náuseas y sensibilidad a luces o sonidos.","source":{"title":"Migraña","url":"https://medlineplus.gov/spanish/migraine.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Respetar la experiencia que estás viviendo","reflection":"Si tu jornada cambia por una migraña, puedes reconocer cómo te afecta y qué necesitas comunicar. En la contemplación, la Llama puede representar una presencia discreta, que te permite estar contigo a tu propio ritmo.","questions":["¿Qué emoción aparece cuando tengo que cambiar mis planes?","¿Qué necesito que comprendan quienes me acompañan?","¿Qué expectativa puedo revisar hoy con amabilidad?"],"phrase":"Mi experiencia merece escucha y mi ritmo merece respeto.","editorialStatus":"propuesta_editorial","suggestedIntents":["adaptacion","expresion","compasion"]},{"id":"miomas-uterinos","title":"Miomas uterinos","category":"Salud ginecológica","aliases":["fibromas uterinos","fibroides uterinos","leiomiomas uterinos"],"definition":"Tumores benignos formados por músculo y otros tejidos que crecen dentro o alrededor de la pared del útero. Pueden variar en tamaño, número y síntomas.","source":{"title":"Fibroides uterinos","url":"https://medlineplus.gov/spanish/uterinefibroids.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Preparar una conversación que te represente","reflection":"Puedes observar qué aspectos de tu experiencia deseas explicar con mayor claridad. La Llama puede acompañar la intención de participar en las conversaciones sobre tu cuidado. Tu vida cotidiana, tus preguntas y tus preferencias pueden ocupar un lugar concreto en lo que decidas compartir.","questions":["¿Qué cambio en mi día quisiera describir mejor?","¿Qué pregunta necesito llevar a mi próxima consulta?","¿Qué preferencia personal quiero hacer visible?"],"phrase":"Puedo dar palabras a mi experiencia y a mis preferencias.","suggestedIntents":["expresion","claridad","apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"narcolepsia","title":"Narcolepsia","category":"Sueño","aliases":["trastorno narcoleptico","narcolepsia tipo 1","narcolepsia tipo 2"],"definition":"Trastorno neurológico que afecta la regulación del sueño y la vigilia. Produce somnolencia diurna intensa y episodios de sueño, y en algunos casos pérdida repentina de tono muscular.","reflectionHeading":"Ser comprendido sin tener que justificarte","reflection":"Que otros confundan tu somnolencia con desinterés puede resultar doloroso. Puedes explorar qué explicación deseas compartir y qué respeto necesitas en tus relaciones. La Llama puede representar la continuidad de tu valor personal, incluso cuando tus tiempos de vigilia no se ajustan a las expectativas ajenas.","questions":["¿Dónde sientes que tu experiencia se interpreta de forma equivocada?","¿Qué límite te ayudaría a sentirte tratado o tratada con respeto?","¿Con quién puedes hablar de los ajustes que necesitas en la vida diaria?"],"phrase":"Mi necesidad de apoyo no disminuye mi compromiso ni mi valor.","suggestedIntents":["expresion","dignidad","limites"],"source":{"title":"Narcolepsia","url":"https://medlineplus.gov/spanish/ency/article/000802.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"neumonia","title":"Neumonía","category":"Infecciones","aliases":["pulmonia","infeccion pulmonar"],"definition":"Infección de uno o ambos pulmones en la que los alvéolos pueden llenarse de líquido o pus. Su intensidad y evolución varían entre las personas.","source":{"title":"Neumonía","url":"https://medlineplus.gov/spanish/pneumonia.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Permitir que te acompañen","reflection":"Si esta experiencia ha interrumpido tu rutina, puedes reconocer cómo estás viviendo la pausa y qué necesitas de otras personas. La imagen de la Llama puede acompañar un momento sencillo de recogimiento, donde recibir ayuda y expresar una necesidad concreta.","questions":["¿Qué me está costando delegar en este momento?","¿Qué ayuda práctica podría pedir con claridad?","¿Qué palabras me gustaría escuchar mientras me cuido?"],"phrase":"Puedo recibir ayuda y dar espacio a mi cuidado.","suggestedIntents":["pedir_apoyo","descanso","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"neuralgia-trigemino","title":"Neuralgia del trigémino","category":"Neurología","aliases":["tic doloroso","neuralgia trigeminal"],"definition":"Trastorno de dolor facial relacionado con el nervio trigémino. Puede provocar episodios intensos, breves y similares a descargas eléctricas, generalmente en un lado del rostro.","reflectionHeading":"Dar lugar al dolor sin quedar reducido a él","reflection":"Cuando el dolor interrumpe acciones sencillas, puede ser difícil explicar cuánto ocupa en tu día. Esta reflexión ofrece un lugar para reconocerlo sin convertirlo en toda tu identidad. Puedes imaginar la Llama como compañía silenciosa, sin pedirte hablar, sonreír o sostener una actitud determinada.","questions":["¿Qué parte de esta experiencia te cuesta más comunicar?","¿Qué compañía respeta mejor tu necesidad de silencio?","¿Qué gesto de consideración te haría sentir menos solo o sola?"],"phrase":"Merezco compañía respetuosa, incluso cuando no tengo palabras.","suggestedIntents":["compasion","dignidad","limites"],"source":{"title":"Neuralgia del trigémino","url":"https://medlineplus.gov/spanish/trigeminalneuralgia.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"neuropatia-periferica","title":"Neuropatía periférica","category":"Neurología","aliases":["neuropatia","daño de nervios perifericos","polineuropatia"],"definition":"Daño de uno o varios nervios fuera del cerebro y la médula espinal. Puede causar dolor, hormigueo, pérdida de sensibilidad o debilidad, según los nervios afectados.","reflectionHeading":"Poner palabras a una experiencia difícil de explicar","reflection":"Las sensaciones difíciles de describir pueden hacer que una conversación sobre el cuerpo resulte agotadora. Puedes elegir palabras sencillas, dibujos o silencios para expresarte. La Llama sirve aquí como imagen de acompañamiento: no exige sentir algo especial ni demostrar tu malestar para merecer comprensión y atención.","questions":["¿Qué palabras describen mejor tu experiencia sin minimizarla?","¿En qué momento te has sentido comprendido o comprendida?","¿Qué ayuda para una tarea cotidiana te gustaría solicitar?"],"phrase":"No necesito explicar perfectamente mi experiencia para merecer cuidado.","suggestedIntents":["expresion","autoacogida","pedir_apoyo"],"source":{"title":"Enfermedades del sistema nervioso periférico","url":"https://medlineplus.gov/spanish/peripheralnervedisorders.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"obesidad","title":"Obesidad","category":"Salud metabólica","aliases":["adiposidad excesiva","obesidad abdominal"],"definition":"Condición caracterizada por una cantidad excesiva de grasa corporal que puede afectar la salud. Intervienen múltiples factores biológicos, ambientales y sociales; su valoración considera el contexto individual.","source":{"title":"Obesidad","url":"https://medlineplus.gov/spanish/obesity.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer tu dignidad en el cuidado","reflection":"Puedes observar cómo te afectan los comentarios, las expectativas y las experiencias de cuidado relacionadas con tu cuerpo. La Llama invita a una presencia digna y completa. Pregúntate qué trato deseas recibir y qué forma de acompañamiento respeta tus necesidades y decisiones.","questions":["¿Qué trato me permite sentirme respetado?","¿Qué comentario o expectativa quisiera poner en palabras?","¿Qué tipo de apoyo se acerca a mis necesidades reales?"],"phrase":"Mi dignidad está presente y puedo elegir un cuidado respetuoso.","suggestedIntents":["dignidad","compasion","limites"],"editorialStatus":"propuesta_editorial"},{"id":"osteoporosis","title":"Osteoporosis","category":"Movimiento y articulaciones","aliases":["fragilidad osea","huesos fragiles","perdida de masa osea"],"definition":"Afección que debilita los huesos por cambios en su densidad, estructura o resistencia. Aumenta la posibilidad de fracturas y con frecuencia se desarrolla sin síntomas evidentes.","source":{"title":"Osteoporosis","url":"https://medlineplus.gov/spanish/osteoporosis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Participar con confianza acompañada","reflection":"Conocer una mayor fragilidad puede despertar preguntas sobre tus actividades y tu autonomía. Puedes escucharlas con cuidado. La Llama acompaña una presencia que conserva capacidad de elección: reconocer tus preferencias, pedir orientación y explorar qué apoyos te permiten seguir participando en tu vida.","questions":["¿Qué actividad me gustaría seguir disfrutando?","¿Qué incertidumbre necesito aclarar para sentirme acompañado?","¿Qué apoyo respetaría mejor mi autonomía?"],"phrase":"Puedo cuidar mi participación y recibir apoyos que respeten mi elección.","suggestedIntents":["pedir_apoyo","adaptacion","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"otitis-media","title":"Otitis media","category":"Oído y equilibrio","aliases":["infeccion del oido medio","otitis","infeccion de oido"],"definition":"Inflamación o infección del oído medio, el espacio situado detrás del tímpano. Puede acompañarse de acumulación de líquido, molestias y cambios temporales en la audición.","reflectionHeading":"Acompañar la incomodidad con sencillez","reflection":"Cuando hay malestar, una presencia paciente puede ser más bienvenida que muchas explicaciones. Si acompañas a un niño, puedes escuchar cómo expresa su incomodidad sin atribuirle un significado emocional oculto. La Llama puede ser una imagen opcional de compañía, ajustada a la edad y a sus preferencias.","questions":["¿Qué forma sencilla de compañía resulta agradable ahora?","¿Cómo se está expresando la incomodidad, con palabras o sin ellas?","¿Qué necesita también la persona que está acompañando?"],"phrase":"Podemos acompañar el malestar con paciencia y atención.","suggestedIntents":["compasion","apoyo","descanso"],"source":{"title":"Infecciones de los oídos","url":"https://medlineplus.gov/spanish/earinfections.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"pancreatitis","title":"Pancreatitis","category":"Salud digestiva","aliases":["inflamacion del pancreas","pancreatitis aguda","pancreatitis cronica"],"definition":"Inflamación del páncreas, órgano que participa en la digestión y en la regulación de la glucosa. Puede presentarse de forma aguda o mantenerse como enfermedad crónica.","source":{"title":"Pancreatitis","url":"https://medlineplus.gov/spanish/pancreatitis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Volver a lo que importa en este momento","reflection":"Si esta experiencia interrumpe tu vida cotidiana, puedes reconocer qué ocupa tu atención y qué apoyo deseas. La Llama puede representar una presencia cercana mientras encuentras palabras para tus emociones y eliges con quién compartir las preguntas de este momento.","questions":["¿Qué es lo que más necesita mi atención hoy?","¿Qué me gustaría que supieran quienes me acompañan?","¿Qué tarea puedo confiar a otra persona?"],"phrase":"Puedo recibir apoyo y atender un momento a la vez.","suggestedIntents":["pedir_apoyo","expresion","compasion"],"editorialStatus":"propuesta_editorial"},{"id":"paralisis-bell","title":"Parálisis de Bell","category":"Neurología","aliases":["paralisis facial de Bell","paralisis del nervio facial"],"definition":"Afección del nervio facial que provoca debilidad o parálisis de aparición rápida, habitualmente en un lado de la cara, y puede afectar el cierre del ojo.","reflectionHeading":"Tu expresión va más allá del rostro","reflection":"Un cambio visible en el rostro puede modificar cómo te sientes al encontrarte con otras personas. Puedes decidir cuánto deseas explicar y qué intimidad conservar. Desde el lenguaje de la Llama, tu presencia y tu valor no dependen de una expresión facial concreta ni de responder a las miradas.","questions":["¿Qué te gustaría que otros supieran al hablar contigo?","¿Qué preguntas prefieres no responder por ahora?","¿Qué forma de expresión te resulta cómoda en este momento?"],"phrase":"Puedo expresar quién soy de muchas maneras y elegir mis límites.","suggestedIntents":["dignidad","expresion","compasion"],"source":{"title":"Parálisis de Bell","url":"https://medlineplus.gov/spanish/bellspalsy.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"psoriasis","title":"Psoriasis","category":"Piel","aliases":["psoriasis en placas","psoriasis cutanea"],"definition":"Enfermedad relacionada con el sistema inmunitario que acelera la renovación de las células cutáneas. Puede formar áreas engrosadas y escamosas, con picazón o dolor.","source":{"title":"Psoriasis","url":"https://medlineplus.gov/spanish/psoriasis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Conservar una mirada amplia sobre ti","reflection":"La manera de verte puede incluir tus vínculos, tus capacidades y aquello que amas. Puedes contemplar la Llama como una imagen de esa presencia completa y explorar cómo quieres participar en tus relaciones.","questions":["¿Qué aspectos de mí quisiera reconocer hoy?","¿Qué necesito para sentirme respetado en mis relaciones?","¿Con quién puedo compartir mi experiencia con libertad?"],"phrase":"Puedo mirarme con amplitud y elegir cómo comparto mi experiencia.","editorialStatus":"propuesta_editorial","suggestedIntents":["dignidad","confianza_discernida","expresion"]},{"id":"perdida-audicion","title":"Pérdida de audición","category":"Oído y equilibrio","aliases":["hipoacusia","perdida auditiva","sordera"],"definition":"Disminución parcial o completa de la capacidad de oír, con distintos grados y causas. Puede afectar la percepción de sonidos y el acceso a conversaciones.","reflectionHeading":"Participar con tu forma de comunicarte","reflection":"Tu pertenencia no depende de escuchar de una manera determinada. Puedes elegir las formas de comunicación que te resulten accesibles y pedir que los encuentros las respeten. En el lenguaje de la Llama, la presencia compartida puede expresarse mediante escritura, señas, imágenes o palabras, según tus preferencias.","questions":["¿Qué forma de comunicación prefieres en este encuentro?","¿Qué cambio ayudaría a que participaras con más comodidad?","¿Qué te gustaría que las personas comprendieran sobre tu identidad y tus preferencias?"],"phrase":"Mi forma de comunicarme merece espacio, acceso y respeto.","suggestedIntents":["expresion","adaptacion","limites"],"source":{"title":"Problemas de la audición y sordera","url":"https://medlineplus.gov/spanish/hearingdisordersanddeafness.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"reflujo","title":"Reflujo gastroesofágico","category":"Salud digestiva","aliases":["ERGE","RGE","acidez cronica","reflujo acido"],"definition":"Retorno del contenido del estómago hacia el esófago, que puede producir ardor o regurgitación. Cuando es persistente o causa daño, puede constituir enfermedad por reflujo gastroesofágico.","source":{"title":"Reflujo gastroesofágico","url":"https://medlineplus.gov/spanish/gerd.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar palabras a tu experiencia","reflection":"Una molestia que vuelve puede ocupar espacio en tu día. Puedes escuchar cómo la estás viviendo y reconocer qué necesitas para sentirte acompañado. La Llama invita a sostener esa conversación interior con respeto y sencillez.","questions":["¿Cómo está afectando esta experiencia a mis actividades?","¿Qué necesito explicar con más claridad?","¿Qué gesto de amabilidad puedo ofrecerme hoy?"],"phrase":"Puedo nombrar mi experiencia y recibirla con respeto.","editorialStatus":"propuesta_editorial","suggestedIntents":["expresion","compasion","autoacogida"]},{"id":"retinopatia-diabetica","title":"Retinopatía diabética","category":"Visión","aliases":["daño retiniano por diabetes","retinopatia por diabetes"],"definition":"Complicación de la diabetes que afecta los vasos sanguíneos de la retina. Puede dañar la visión y, en sus primeras etapas, no producir síntomas evidentes.","reflectionHeading":"Cuidarte sin convertir el diagnóstico en reproche","reflection":"Vivir una complicación puede despertar cansancio, temor o preguntas difíciles. Puedes atender esas emociones sin convertirlas en un juicio sobre tu valor. En esta propuesta, la Llama recuerda la dignidad de quien recibe cuidado. También puedes pedir ayuda para organizar conversaciones y decisiones que se sienten numerosas.","questions":["¿Qué emoción aparece al hablar de esta complicación?","¿Qué mensaje de reproche te gustaría reemplazar por un trato más respetuoso?","¿Qué ayuda práctica necesitas para manejar la información y las citas?"],"phrase":"Merezco cuidado y respeto mientras atravieso este proceso.","suggestedIntents":["compasion","pedir_apoyo","claridad"],"source":{"title":"Problemas de los ojos asociados con la diabetes","url":"https://medlineplus.gov/spanish/diabeticeyeproblems.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"rosacea","title":"Rosácea","category":"Piel","aliases":["acne rosacea","rosacea facial"],"definition":"Afección crónica que suele producir enrojecimiento y pequeñas lesiones en el rostro. En algunas personas también afecta los ojos, con molestias como sequedad o irritación.","source":{"title":"Rosácea","url":"https://medlineplus.gov/spanish/rosacea.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Encontrarte con otros desde tu propia voz","reflection":"Si los cambios visibles de tu piel influyen en cómo te sientes al encontrarte con otras personas, puedes dar lugar a esa experiencia. La Llama acompaña una mirada respetuosa hacia ti y la posibilidad de expresar cómo deseas ser tratado.","questions":["¿Cómo me siento al participar en un encuentro social?","¿Qué necesito para sentirme respetado en una conversación?","¿Qué parte de mí quisiera compartir más allá de mi apariencia?"],"phrase":"Puedo encontrarme con otros desde mi voz y mi dignidad.","suggestedIntents":["dignidad","expresion","limites"],"editorialStatus":"propuesta_editorial"},{"id":"sinusitis","title":"Sinusitis","category":"Oído, nariz y garganta","aliases":["rinosinusitis","infeccion de senos paranasales","sinusitis cronica"],"definition":"Inflamación de los senos paranasales, cavidades alrededor de la nariz. Puede causar congestión, presión o dolor facial y secreciones, y presentarse de forma breve o persistente.","reflectionHeading":"Dar espacio a un día con menos recursos","reflection":"La congestión y el malestar pueden hacer que las tareas habituales se sientan más pesadas. Puedes revisar cuánto deseas sostener hoy y comunicarlo sin culpa. La imagen de la Llama acompaña ese gesto de cuidado; la contemplación no requiere respiraciones forzadas, aromas ni demostrar resistencia a la incomodidad.","questions":["¿Qué tarea podrías compartir o posponer sin exigirte de más?","¿Qué necesitas explicar sobre cómo te sientes hoy?","¿Qué compañía te resulta agradable cuando tienes menos disposición para conversar?"],"phrase":"Puedo reconocer mis límites de hoy y pedir consideración.","suggestedIntents":["descanso","limites","apoyo"],"source":{"title":"Sinusitis","url":"https://medlineplus.gov/spanish/sinusitis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"cushing","title":"Síndrome de Cushing","category":"Salud hormonal","aliases":["hipercortisolismo","Cushing"],"definition":"Trastorno producido por exposición prolongada a cantidades excesivas de cortisol. Puede acompañarse de cambios en la distribución de grasa, debilidad muscular, alteraciones de la piel y otros síntomas.","source":{"title":"Síndrome de Cushing","url":"https://medlineplus.gov/spanish/cushingsyndrome.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Encontrarte más allá de los cambios","reflection":"Si los cambios corporales o anímicos afectan la forma en que te reconoces, puedes darles palabras y compañía. La Llama invita a una mirada amplia sobre tu presencia. También forman parte de ti tus vínculos, tus intereses y la manera en que deseas ser escuchado.","questions":["¿Qué aspecto de mi experiencia quisiera explicar mejor?","¿Qué parte de mí deseo seguir cultivando?","¿Qué compañía me ayuda a sentirme reconocido?"],"phrase":"Puedo recibir los cambios con compañía y conservar una mirada amplia sobre mí.","suggestedIntents":["dignidad","autoacogida","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"ovario-poliquistico","title":"Síndrome de ovario poliquístico","category":"Salud hormonal","aliases":["SOP","ovarios poliquisticos","PCOS","SOMP"],"definition":"Conjunto de alteraciones hormonales que puede incluir ovulación irregular, exceso de andrógenos y cambios en los ovarios. Sus manifestaciones y repercusiones varían de una persona a otra.","source":{"title":"Síndrome de ovario poliquístico","url":"https://medlineplus.gov/spanish/polycysticovarysyndrome.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Escuchar tus propios deseos","reflection":"Puedes explorar cómo esta experiencia se encuentra con tus deseos, tu imagen corporal o tus planes de vida. La Llama ofrece una imagen de escucha donde tu voz tiene lugar. Cada pregunta puede abrir una conversación elegida por ti, a tu propio ritmo.","questions":["¿Qué deseo propio quisiera distinguir de las expectativas de otros?","¿Qué aspecto de mi experiencia necesito comprender mejor?","¿Qué conversación quiero tener sobre mis planes o mi intimidad?"],"phrase":"Mis deseos y mis preguntas pueden tener una voz propia.","suggestedIntents":["eleccion_consciente","expresion","autoacogida"],"editorialStatus":"propuesta_editorial"},{"id":"piernas-inquietas","title":"Síndrome de piernas inquietas","category":"Sueño","aliases":["sindrome de las piernas inquietas","SPI","enfermedad de Willis-Ekbom"],"definition":"Trastorno que genera una necesidad intensa de mover las piernas, generalmente acompañada de sensaciones desagradables durante el reposo. Puede interferir con el inicio y mantenimiento del sueño.","reflectionHeading":"Sin exigirte una quietud perfecta","reflection":"Si la incomodidad dificulta permanecer quieto, no tienes que convertir la contemplación en otra prueba. Puedes acercarte al lenguaje de la Llama con la duración y la forma que te resulten amables. La inquietud corporal no indica un fracaso personal ni falta de disposición espiritual.","questions":["¿Qué exigencias te impones cuando intentas descansar?","¿Qué forma de compañía te resulta agradable en una noche difícil?","¿Qué quisieras que quienes conviven contigo comprendieran sobre esta experiencia?"],"phrase":"No necesito una quietud perfecta para tratarme con amabilidad.","suggestedIntents":["descanso","compasion","apoyo"],"source":{"title":"Síndrome de las piernas inquietas","url":"https://medlineplus.gov/spanish/restlesslegs.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"sjogren","title":"Síndrome de Sjögren","category":"Enfermedades autoinmunes","aliases":["enfermedad de Sjogren","sindrome de Sjogren","Sjogren"],"definition":"Enfermedad autoinmune que afecta especialmente las glándulas que producen lágrimas y saliva. Puede ocasionar sequedad de ojos y boca, además de manifestaciones en otras partes del cuerpo.","source":{"title":"Enfermedad de Sjögren","url":"https://medlineplus.gov/spanish/sjogrensdisease.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Dar valor a las necesidades cotidianas","reflection":"Puedes explorar cómo las pequeñas incomodidades repetidas participan en tu jornada y qué te gustaría que otros comprendieran. En la contemplación de la Llama, esas necesidades pueden recibir atención y palabras, junto con tus deseos de conversación, compañía y participación.","questions":["¿Qué situación cotidiana quisiera hacer más llevadera?","¿Qué necesito explicar a quienes comparten mi día?","¿Qué momento de compañía me gustaría cuidar?"],"phrase":"Mis necesidades cotidianas merecen atención y palabras claras.","suggestedIntents":["expresion","apoyo","compasion"],"editorialStatus":"propuesta_editorial"},{"id":"intestino-irritable","title":"Síndrome del intestino irritable","category":"Salud digestiva","aliases":["SII","IBS","colon irritable"],"definition":"Conjunto de síntomas que combina dolor abdominal recurrente y cambios en las deposiciones, como diarrea, estreñimiento o ambos, sin lesiones visibles que expliquen esos síntomas.","source":{"title":"Definición e información para el síndrome del intestino irritable","url":"https://www.niddk.nih.gov/health-information/informacion-de-la-salud/enfermedades-digestivas/sindrome-intestino-irritable/definicion-hechos","organization":"NIDDK · Institutos Nacionales de la Salud","verifiedDate":"2026-10-26"},"reflectionHeading":"Conservar espacio para tu vida","reflection":"Cuando la experiencia corporal cambia de un día a otro, puedes preguntarte cómo mantener espacio para tus vínculos, tus proyectos y tu intimidad. La Llama acompaña la posibilidad de reconocer tus necesidades y hacerlas parte de tus decisiones.","questions":["¿Qué aspecto de mi vida quisiera seguir cultivando?","¿Qué necesito conversar para sentirme más acompañado?","¿Qué puedo elegir hoy sin exigirme resolver todo a la vez?"],"phrase":"Mis necesidades pueden tener un lugar en mis decisiones.","editorialStatus":"propuesta_editorial","suggestedIntents":["adaptacion","eleccion_consciente","expresion"]},{"id":"ojo-seco","title":"Síndrome del ojo seco","category":"Visión","aliases":["ojo seco","sequedad ocular","queratoconjuntivitis seca"],"definition":"Afección en la que la superficie del ojo no conserva una película lagrimal adecuada. Puede causar ardor, sensación arenosa, irritación y visión borrosa.","reflectionHeading":"Reconocer pequeñas molestias que sí importan","reflection":"Una molestia que parece pequeña para otros puede ocupar mucho espacio en tu día. Puedes reconocer ese impacto sin tener que exagerarlo o restarle importancia. La Llama se propone como imagen de atención amable; tu práctica puede ser breve y no requiere mirar símbolos ni mantener la vista fija.","questions":["¿Qué actividad cotidiana se ha vuelto más demandante para ti?","¿Qué necesitas comunicar a quienes esperan que sigas como siempre?","¿Qué forma de pausa se siente amable dentro de tus posibilidades?"],"phrase":"Mis molestias merecen atención, aunque otras personas no las vean.","suggestedIntents":["descanso","limites","expresion"],"source":{"title":"Síndrome del ojo seco","url":"https://medlineplus.gov/spanish/ency/article/000426.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"sindrome-tunel-carpiano","title":"Síndrome del túnel carpiano","category":"Movimiento y articulaciones","aliases":["tunel carpiano","tunel carpal","compresion del nervio mediano"],"definition":"Compresión del nervio mediano al pasar por la muñeca, que puede producir hormigueo, entumecimiento, dolor o debilidad en la mano y afectar tareas cotidianas.","source":{"title":"Síndrome del túnel carpiano","url":"https://medlineplus.gov/spanish/carpaltunnelsyndrome.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer otra manera de hacer","reflection":"Si algunas tareas se vuelven difíciles, puedes explorar qué significan para ti y qué ayuda estarías dispuesto a recibir. La Llama acompaña una presencia que conserva valor en cada forma de participar, mientras conversas sobre tu ritmo y tus posibilidades actuales.","questions":["¿Qué tarea importante para mí está siendo más difícil?","¿Qué ayuda o cambio quisiera conversar en mi trabajo o mi hogar?","¿Cómo puedo reconocer mi valor más allá de lo que logro hacer?"],"phrase":"Mi valor permanece y puedo encontrar nuevas formas de participar.","suggestedIntents":["adaptacion","pedir_apoyo","limites"],"editorialStatus":"propuesta_editorial"},{"id":"tinnitus","title":"Tinnitus","category":"Oído y equilibrio","aliases":["acufenos","zumbido en los oidos","silbidos en los oidos"],"definition":"Percepción de sonidos, como zumbidos o silbidos, sin una fuente sonora externa correspondiente. Puede sentirse en uno o ambos oídos y variar en intensidad y duración.","reflectionHeading":"No exigir silencio para merecer una pausa","reflection":"Si el sonido ocupa tu atención, puedes sentir frustración cuando alguien te pide simplemente ignorarlo. Esta propuesta no exige silencio interno o externo. La Llama puede ser una imagen elegida de presencia amable mientras reconoces lo que estás viviendo y decides qué apoyo deseas recibir.","questions":["¿Qué comentarios sobre tu experiencia te ayudan y cuáles te incomodan?","¿Qué te gustaría comunicar acerca de su impacto en tu día?","¿Qué expectativa de silencio perfecto puedes dejar fuera de tu práctica?"],"phrase":"Puedo reconocer lo que escucho sin juzgarme por cómo me afecta.","suggestedIntents":["compasion","descanso","expresion"],"source":{"title":"Tinnitus","url":"https://medlineplus.gov/spanish/tinnitus.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"hashimoto","title":"Tiroiditis de Hashimoto","category":"Salud hormonal","aliases":["enfermedad de Hashimoto","tiroiditis cronica","Hashimoto"],"definition":"Trastorno autoinmune en el que el sistema inmunitario afecta la glándula tiroides. Con frecuencia disminuye su producción de hormonas y conduce a hipotiroidismo a lo largo del tiempo.","source":{"title":"Tiroiditis crónica (Enfermedad de Hashimoto)","url":"https://medlineplus.gov/spanish/ency/article/000371.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Cultivar una relación paciente contigo","reflection":"Puedes preguntarte cómo estás viviendo los cambios de energía, las consultas o la espera de respuestas. La Llama puede representar una presencia paciente mientras comprendes tu proceso. Reconoce lo que sabes hoy y lo que deseas conversar, dejando espacio para tus sentimientos.","questions":["¿Qué estoy aprendiendo de mi experiencia cotidiana?","¿Qué pregunta sigue abierta para mí?","¿Cómo quiero acompañarme mientras avanzo en mi seguimiento?"],"phrase":"Puedo acompañar mi proceso con paciencia y preguntas propias.","suggestedIntents":["compasion","constancia_cuidada","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"trastorno-bipolar","title":"Trastorno bipolar","category":"Salud mental","aliases":["bipolaridad","trastorno bipolar I","trastorno bipolar II"],"definition":"Trastorno del estado de ánimo con episodios de manía o hipomanía y, con frecuencia, depresión. Puede modificar de forma importante la energía, la actividad y el comportamiento.","source":{"title":"Trastorno bipolar","url":"https://medlineplus.gov/spanish/bipolardisorder.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Sostener vínculos y decisiones con paciencia","reflection":"Puedes explorar qué rutinas, vínculos y acuerdos te ayudan a participar en tu vida cotidiana. Dentro de esta contemplación, la Llama representa una presencia serena y cercana. Puedes darle tiempo a tus decisiones y compartir tus observaciones con las personas que conocen tu proceso.","questions":["¿Qué acuerdo cotidiano me resulta útil sostener?","¿Con quién puedo revisar una decisión importante?","¿Qué cambio quisiera comunicar a mi equipo de apoyo?"],"phrase":"Puedo dar tiempo a mis decisiones y recibir una mirada cercana.","suggestedIntents":["constancia_cuidada","pedir_apoyo","claridad"],"editorialStatus":"propuesta_editorial"},{"id":"ansiedad-generalizada","title":"Trastorno de ansiedad generalizada","category":"Salud mental","aliases":["TAG","ansiedad generalizada"],"definition":"Trastorno caracterizado por preocupación persistente y difícil de controlar sobre diferentes asuntos cotidianos. Puede acompañarse de inquietud, tensión muscular, problemas de concentración y alteraciones del sueño.","source":{"title":"Trastorno de ansiedad generalizada","url":"https://medlineplus.gov/spanish/ency/article/000917.htm","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Abrir espacio a una preocupación concreta","reflection":"Si las preocupaciones ocupan mucho espacio, puedes elegir una experiencia pequeña para nombrarla. La Llama puede ser una imagen de compañía durante esa conversación contigo. Quizás hoy quieras distinguir una pregunta concreta, reconocer un apoyo o compartir cómo estás viviendo el día.","questions":["¿Qué preocupación quisiera expresar con palabras sencillas?","¿Qué parte de esta situación puedo conversar con alguien?","¿Qué apoyo me gustaría recibir hoy?"],"phrase":"Puedo acercarme a una pregunta cada vez.","suggestedIntents":["claridad","expresion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"estres-postraumatico","title":"Trastorno de estrés postraumático","category":"Salud mental","aliases":["TEPT","PTSD","estres postraumatico"],"definition":"Afección que puede aparecer después de vivir o presenciar un acontecimiento traumático. Puede incluir recuerdos intrusivos, evitación, cambios del ánimo y una alerta persistente.","source":{"title":"Trastorno de estrés postraumático","url":"https://medlineplus.gov/spanish/posttraumaticstressdisorder.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Respetar tu ritmo y tu elección","reflection":"Puedes centrar esta reflexión en el presente y en las condiciones que te permiten sentirte acompañado. Si la imagen de la Llama te resulta agradable, recíbela como una presencia tranquila. Tu elección sobre cuánto compartir, con quién y en qué momento conserva su lugar.","questions":["¿Qué me ayuda a reconocer que estoy aquí, en este momento?","¿Qué condiciones necesito para una conversación respetuosa?","¿Qué preferiría reservarme hoy?"],"phrase":"Mi ritmo y mi elección merecen respeto.","suggestedIntents":["limites","apoyo","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"trastorno-panico","title":"Trastorno de pánico","category":"Salud mental","aliases":["trastorno de panico"],"definition":"Afección que presenta ataques de pánico repetidos e inesperados, junto con preocupación por su repetición o cambios de comportamiento que pueden limitar la vida cotidiana.","source":{"title":"Trastorno de pánico","url":"https://medlineplus.gov/spanish/panicdisorder.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Recibir compañía en un momento tranquilo","reflection":"En un momento tranquilo, puedes explorar cómo quieres ser acompañado cuando una experiencia te asusta. La imagen de la Llama puede recordarte la presencia de vínculos y apoyos concretos. Puedes elegir palabras sencillas para expresar tu necesidad y decidir cuánto deseas compartir.","questions":["¿Qué tipo de compañía me resulta respetuosa?","¿Qué me gustaría explicar a alguien de confianza?","¿Qué lugar o actividad cotidiana quisiera volver a conversar con mi equipo de apoyo?"],"phrase":"Puedo dar voz a lo que necesito y recibir compañía.","suggestedIntents":["apoyo","compasion","pedir_apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"trastorno-obsesivo-compulsivo","title":"Trastorno obsesivo-compulsivo","category":"Salud mental","aliases":["TOC","trastorno obsesivo compulsivo"],"definition":"Afección caracterizada por pensamientos intrusivos recurrentes y comportamientos o actos mentales repetitivos. Las obsesiones y compulsiones pueden consumir tiempo y afectar significativamente la vida diaria.","source":{"title":"Trastorno obsesivo-compulsivo","url":"https://medlineplus.gov/spanish/obsessivecompulsivedisorder.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Encontrar una relación amable con la incertidumbre","reflection":"Puedes explorar qué apoyos hacen espacio a tu vida cotidiana cuando la incertidumbre resulta difícil. La Llama es aquí una imagen opcional de compañía. Puedes contemplarla brevemente, dejarla a un lado y conversar con alguien sobre aquello que deseas seguir cultivando en tu día.","questions":["¿Qué actividad importante para mí quisiera acompañar?","¿Qué apoyo facilita mi día sin añadir nuevas exigencias?","¿Qué deseo conversar con la persona que me acompaña profesionalmente?"],"phrase":"Puedo recibir apoyo sin tener que resolverlo todo ahora.","suggestedIntents":["compasion","pedir_apoyo","autoacogida"],"editorialStatus":"propuesta_editorial"},{"id":"trastorno-atracon","title":"Trastorno por atracón","category":"Conducta alimentaria","aliases":["trastorno por atracones","trastorno de atracon"],"definition":"Trastorno alimentario con episodios recurrentes de ingesta abundante y sensación de pérdida de control, asociados a malestar significativo, sin conductas compensatorias regulares como las de la bulimia.","source":{"title":"Definición y hechos del trastorno por atracón","url":"https://www.niddk.nih.gov/health-information/informacion-de-la-salud/control-de-peso/trastorno-por-atracon/definicion-hechos","organization":"NIDDK · Institutos Nacionales de la Salud","verifiedDate":"2026-10-26"},"reflectionHeading":"Encontrar una escucha respetuosa","reflection":"Puedes observar qué necesitas para hablar de tu experiencia con confianza. La imagen de la Llama puede acompañar una mirada amplia hacia tu vida: tus relaciones, tus intereses y tu necesidad de cuidado. Elige una pregunta que abra una conversación amable y concreta.","questions":["¿Qué necesito que otra persona comprenda sobre mi experiencia?","¿Qué tipo de comentario me ayuda y cuál prefiero evitar?","¿Con quién quisiera conversar sobre el apoyo que busco?"],"phrase":"Puedo pedir una escucha que respete mi dignidad.","suggestedIntents":["autoacogida","compasion","limites"],"editorialStatus":"propuesta_editorial"},{"id":"tdah","title":"Trastorno por déficit de atención e hiperactividad","category":"Neurodesarrollo","aliases":["TDAH","ADHD","deficit de atencion e hiperactividad"],"definition":"Trastorno del neurodesarrollo que implica dificultades persistentes de atención, impulsividad y, en algunas personas, hiperactividad. Comienza en la infancia y puede continuar durante la vida adulta.","source":{"title":"Trastorno de déficit de atención e hiperactividad","url":"https://medlineplus.gov/spanish/attentiondeficithyperactivitydisorder.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer tu manera de participar","reflection":"Puedes observar qué condiciones facilitan que una tarea tenga un comienzo claro para ti. La Llama puede acompañar una intención concreta y pequeña. También puedes reconocer tus intereses, pedir un acuerdo más sencillo y dar palabras a la forma de apoyo que te resulta útil.","questions":["¿Qué tarea quiero mirar de una en una?","¿Qué cambio en el entorno me ayudaría a participar?","¿Cómo puedo explicar la ayuda que necesito?"],"phrase":"Puedo encontrar una forma de participar que reconozca mis necesidades.","suggestedIntents":["adaptacion","dignidad","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"trombosis-venosa-profunda","title":"Trombosis venosa profunda","category":"Salud cardiovascular","aliases":["TVP","trombosis venosa","flebotrombosis"],"definition":"Formación de un coágulo dentro de una vena profunda, habitualmente en la pierna. El coágulo puede obstaculizar la circulación y, si se desprende, desplazarse hacia los pulmones.","source":{"title":"Trombosis venosa profunda","url":"https://medlineplus.gov/spanish/deepveinthrombosis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Acompañarte durante un proceso de cuidado","reflection":"Durante el seguimiento de esta condición, pueden aparecer preguntas sobre lo que viene y sobre cómo organizar tu vida. La Llama ofrece una imagen de compañía para reconocer esas inquietudes. Puedes elegir qué necesitas comprender y qué ayuda deseas recibir en lo cotidiano.","questions":["¿Qué inquietud quisiera expresar durante mi seguimiento?","¿Qué tarea me vendría bien compartir con alguien?","¿Qué me ayuda a sentirme acompañado mientras atravieso este proceso?"],"phrase":"Puedo dar voz a mis preguntas y recibir compañía en mi cuidado.","suggestedIntents":["incertidumbre","pedir_apoyo","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"tuberculosis","title":"Tuberculosis","category":"Infecciones","aliases":["TB","infeccion tuberculosa"],"definition":"Enfermedad causada por una bacteria que suele afectar los pulmones, aunque puede comprometer otros órganos. La infección puede permanecer inactiva o manifestarse como enfermedad activa.","source":{"title":"Tuberculosis","url":"https://medlineplus.gov/spanish/tuberculosis.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Sostener los vínculos durante el cuidado","reflection":"Puedes explorar cómo quieres mantener tus vínculos mientras atraviesas este proceso. La Llama ofrece una imagen de compañía y dignidad que puede estar presente en una conversación, en el silencio compartido o en la expresión de aquello que necesitas comprender.","questions":["¿Con quién deseo mantener una conversación cercana?","¿Qué información necesito comprender mejor sobre mi proceso?","¿Qué gesto de compañía me haría sentir reconocido?"],"phrase":"Puedo atravesar este proceso con dignidad, información y compañía.","suggestedIntents":["reciprocidad","pedir_apoyo","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"urticaria","title":"Urticaria","category":"Piel","aliases":["ronchas","habones"],"definition":"Aparición de ronchas elevadas en la piel, frecuentemente acompañadas de picazón. Pueden surgir por diferentes desencadenantes y cambiar de forma o de lugar con el tiempo.","source":{"title":"Urticaria","url":"https://medlineplus.gov/spanish/hives.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Recibir el momento con amabilidad","reflection":"Si la incomodidad ocupa tu atención, puedes reconocer cómo está afectando tu ánimo y tus planes. La Llama puede representar un espacio amable donde poner en palabras lo que estás viviendo y elegir qué compañía o privacidad te gustaría tener.","questions":["¿Qué emoción acompaña esta incomodidad?","¿Qué quiero comunicar sobre cómo estoy hoy?","¿Prefiero compañía, privacidad o ayuda práctica en este momento?"],"phrase":"Puedo reconocer lo que siento y elegir cómo acompañarme.","suggestedIntents":["compasion","expresion","apoyo"],"editorialStatus":"propuesta_editorial"},{"id":"vih","title":"VIH","category":"Infecciones","aliases":["virus de inmunodeficiencia humana","infeccion por VIH"],"definition":"Virus que afecta al sistema inmunitario al dañar células que participan en la defensa frente a infecciones. La infección por VIH y el sida describen situaciones diferentes.","source":{"title":"VIH","url":"https://medlineplus.gov/spanish/hiv.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Elegir cómo compartes tu experiencia","reflection":"Tu experiencia puede tener el lugar y la intimidad que tú elijas. En la contemplación de la Llama, puedes reconocer tu dignidad, los vínculos que te sostienen y las conversaciones que deseas abrir, conservando tu voz en las decisiones sobre tu vida.","questions":["¿Con quién me siento respetado y escuchado?","¿Qué deseo compartir y qué prefiero reservarme?","¿Qué apoyo facilitaría un proyecto que me importa?"],"phrase":"Mi dignidad permanece y puedo elegir cómo comparto mi vida.","suggestedIntents":["dignidad","limites","confianza_discernida"],"editorialStatus":"propuesta_editorial"},{"id":"vitiligo","title":"Vitíligo","category":"Piel","aliases":["vitiligo","despigmentacion por vitiligo"],"definition":"Pérdida de pigmentación que produce áreas más claras en la piel al desaparecer células que generan color. Puede afectar también el cabello y ciertas mucosas.","source":{"title":"Vitiligo","url":"https://medlineplus.gov/spanish/vitiligo.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Habitar tu imagen con libertad","reflection":"Puedes preguntarte cómo deseas relacionarte con tu imagen y con las miradas de otras personas. La Llama puede acompañar una presencia propia, donde tus preferencias y tus límites encuentren palabras, y donde tus relaciones tengan espacio para reconocerte de manera completa.","questions":["¿Cómo quiero relacionarme con mi imagen hoy?","¿Qué preguntas sobre mi piel deseo responder y cuáles prefiero reservarme?","¿Qué personas me reconocen de una manera amplia y cercana?"],"phrase":"Puedo habitar mi imagen y elegir cómo participo en mis relaciones.","suggestedIntents":["dignidad","limites","autoacogida"],"editorialStatus":"propuesta_editorial"},{"id":"varices","title":"Várices","category":"Salud cardiovascular","aliases":["varices","venas varicosas","venas dilatadas"],"definition":"Venas dilatadas y retorcidas visibles bajo la piel, con mayor frecuencia en las piernas. Pueden acompañarse de pesadez, dolor u otras molestias, aunque algunas no causan síntomas.","source":{"title":"Várices","url":"https://medlineplus.gov/spanish/varicoseveins.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Escuchar tus preferencias cotidianas","reflection":"Puedes explorar cómo estás viviendo las molestias o los cambios visibles en tus piernas. La contemplación de la Llama invita a reconocer tu comodidad y tus preferencias. Tal vez quieras conversar sobre tus tareas, tu descanso o la manera en que te miras.","questions":["¿Qué parte de mi jornada quisiera organizar de otra manera?","¿Cómo quiero hablarme al observar mi cuerpo?","¿Qué preferencia necesito expresar a quienes comparten mi día?"],"phrase":"Mi comodidad y mis preferencias merecen un lugar en mi día.","suggestedIntents":["descanso","compasion","expresion"],"editorialStatus":"propuesta_editorial"},{"id":"vertigo","title":"Vértigo","category":"Oído y equilibrio","aliases":["sensacion de giro","vertigo posicional","mareo con giro"],"definition":"Sensación de que uno mismo o el entorno giran aunque permanezcan inmóviles. Es un síntoma con varias causas posibles y puede acompañarse de náuseas o inestabilidad.","reflectionHeading":"Aceptar compañía cuando falta seguridad","reflection":"La sensación de giro puede cambiar tu confianza al realizar actividades habituales. Puedes reconocer esa incertidumbre y conversar sobre la ayuda que deseas. La imagen de la Llama se ofrece como referencia simbólica de compañía, sin exigirte cerrar los ojos, visualizar movimientos ni probar tu capacidad de equilibrio.","questions":["¿Qué situación cotidiana te genera más incertidumbre ahora?","¿Qué acompañamiento te haría sentir respetado o respetada?","¿Qué necesidad puedes comunicar antes de intentar cumplir una expectativa ajena?"],"phrase":"Pedir compañía también es una forma de cuidar mi autonomía.","suggestedIntents":["apoyo","pedir_apoyo","limites"],"source":{"title":"Mareo y vértigo","url":"https://medlineplus.gov/spanish/dizzinessandvertigo.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-27"},"editorialStatus":"propuesta_editorial"},{"id":"ulcera-peptica","title":"Úlcera péptica","category":"Salud digestiva","aliases":["ulcera gastrica","ulcera duodenal","ulcera de estomago"],"definition":"Lesión abierta en el revestimiento del estómago o del duodeno, la primera parte del intestino delgado. Puede producir dolor o ardor en la zona abdominal.","source":{"title":"Úlcera péptica","url":"https://medlineplus.gov/spanish/pepticulcer.html","organization":"MedlinePlus · Biblioteca Nacional de Medicina de EE. UU.","verifiedDate":"2026-10-26"},"reflectionHeading":"Reconocer lo que necesitas hoy","reflection":"Puedes acercarte a tu experiencia con preguntas concretas y reconocer cómo está afectando tu día. En el lenguaje de la Llama, la presencia interior acompaña el cuidado que eliges: pedir información, ordenar una conversación o recibir ayuda en una tarea cotidiana.","questions":["¿Qué aspecto de mi día está necesitando más atención?","¿Qué información quiero aclarar con quienes me atienden?","¿Qué apoyo práctico podría pedir hoy?"],"phrase":"Puedo atender mis necesidades y hacer espacio para recibir ayuda.","suggestedIntents":["claridad","apoyo","expresion"],"editorialStatus":"propuesta_editorial"}]};
